window.EXAM_STUDIES = window.EXAM_STUDIES || {}; window.EXAM_STUDIES[14] = {"1":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>הוכיחו את משפט בולצאנו-ויירשטראס (משפט 3.32): לכל סדרה חסומה יש תת סדרה מתכנסת.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כשאינסוף מספרים דחוסים בתוך קטע סופי אחד, חייב להיות מקום בקטע שמסביבו הם מצטופפים — ואפשר ללכוד אותו על ידי חצייה חוזרת לשניים.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כשאינסוף מספרים דחוסים בתוך קטע סופי אחד, חייב להיות מקום בקטע שמסביבו הם מצטופפים — ואפשר ללכוד אותו על ידי חצייה חוזרת לשניים.</p>\n<p><strong>תמונה בראש</strong>: דמיינו אינסוף קופצים שנמצאים בתוך מסדרון באורך מוגבל, למשל <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(-10\\)</span></span> עד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(10\\)</span>.</span> נחלק את המסדרון לחצי: לפחות בחצי אחד חייבים להיות אינסוף קופצים (אחרת בסך הכול היו רק מספר סופי!). נמשיך לחלק את החצי העמוס שוב ושוב: החדרים נהיים זעירים עד שמתכווצים לנקודה אחת בלבד, ונוכל לבחור קופץ אחד מכל חדר לפי הסדר שכולם יתקרבו לאותה נקודה.</p>\n<p><strong>עם מספרים</strong>: בסדרה <span class=\"math math-inline\" dir=\"ltr\">\\(a_n = (-1)^n + \\frac{1}{n}\\)</span> כל האיברים כלואים בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([-2, 2]\\)</span>.</span> נחלק <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\([-2, 0]\\)</span></span> <span class=\"nobr\">ול-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0, 2]\\)</span>:</span></span> בשני המקרים יש אינסוף איברים! נבחר למשל את <span class=\"math math-inline\" dir=\"ltr\">\\([0, 2]\\)</span> (כל הזוגיים שם), נחלק <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span></span> <span class=\"nobr\">ול-<span class=\"math math-inline\" dir=\"ltr\">\\([1,2]\\)</span></span> — <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([1,2]\\)</span></span> יש אינסוף איברים (כל האיברים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k}=1+\\frac{1}{2k}\\)</span>).</span> ממשיכים להצטופף אל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=1\\)</span>,</span> והזוגיים נותנים תת־סדרה שמתכנסת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></p>\n<p><strong>מושגים</strong>:</p>\n<ul><li><strong>סדרה חסומה (הגדרה 2.15)</strong>: קיים מספר חיובי <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> כך שכל איברי הסדרה נמצאים בתוך הקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([-M, M]\\)</span>.</span></li><li><strong>תת־סדרה (הגדרה 3.24)</strong>: בחירה של אינסוף איברים מהסדרה בסדר עולה של מקומות <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(n_1 &lt; n_2 &lt; n_3 &lt; \\dots\\)</span>).</span></li><li><strong>הלמה של קנטור (משפט 3.22)</strong>: אם סדרה של קטעים סגורים נכנסת זו לזו ואורכה שואף לאפס, יש נקודה יחידה שנמצאת בתוך כל הקטעים.</li></ul></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><figure class=\"demo\" id=\"demo-nested-intervals\" data-demo=\"nested-intervals\"><noscript><p>ההמחשה האינטראקטיבית דורשת JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: למה תמיד נשאר חצי שיש בו אינסוף אינדקסים?","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: למה תמיד נשאר חצי שיש בו אינסוף אינדקסים?</p><div class=\"callout-body\"><p>אם בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([A_k, B_k]\\)</span> יש אינסוף אינדקסים <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> שעבורם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\in [A_k, B_k]\\)</span>,</span> ומחלקים אותו לשני חצאים <span class=\"math math-inline\" dir=\"ltr\">\\([A_k, m_k]\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\([m_k, B_k]\\)</span></span> — אילו לשני החצאים היו רק מספר סופי של אינדקסים, איחודם היה סופי!</p></div></div>"},{"title":"רמז 2: איך בונים תת-סדרה ממש (שמירה על $n_1 < n_2 < \\dots$) בלי להיתקע?","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: איך בונים תת-סדרה ממש (שמירה על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n_1 &lt; n_2 &lt; \\dots\\)</span>)</span> בלי להיתקע?</p><div class=\"callout-body\"><p>בכל קטע <span class=\"math math-inline\" dir=\"ltr\">\\(I_k\\)</span> יש <em>אינסוף</em> אינדקסים <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\in I_k\\)</span>.</span> לכן אחרי שכבר בחרנו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n_k\\)</span>,</span> תמיד נותר אינדקס <span class=\"math math-inline\" dir=\"ltr\">\\(n_{k+1} &gt; n_k\\)</span> שמתאים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I_{k+1}\\)</span>!</span></span> בסוף מפעילים את קנטור (משפט 3.22) ואת הסנדוויץ׳ (משפט 2.32).</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">תוכנית ההוכחה</p><div class=\"callout-body\"><ol><li>מהחסימות של <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> נקבל שכל איברי הסדרה נמצאים בקטע סגור ראשוני <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I_1=[A_1,B_1]=[-M,M]\\)</span>.</span></li><li>נבנה באינדוקציה סדרה של קטעים סגורים מקוננים <span class=\"math math-inline\" dir=\"ltr\">\\(I_k=[A_k,B_k]\\)</span> שאורכם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{B_1-A_1}{2^{k-1}}\\to 0\\)</span>,</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(k\\)</span> קיימים אינסוף אינדקסים <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> עבורם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\in I_k\\)</span>.</span></li><li>נפעיל את הלמה של קנטור (משפט 3.22) לקבלת נקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\in\\bigcap_{k=1}^\\infty I_k\\)</span>,</span> ונראה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(A_k\\to L\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(B_k\\to L\\)</span>.</span></span></li><li>נבחר באינדוקציה סדרת אינדקסים עולה ממש <span class=\"math math-inline\" dir=\"ltr\">\\(n_1 &lt; n_2 &lt; \\dots\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{n_k}\\in I_k\\)</span>,</span></span> ונסיק ממשפט הסנדוויץ׳ (משפט 2.32) כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{k\\to\\infty} a_{n_k}=L\\)</span>.</span></li></ol></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון</p><div class=\"callout-body\"><p><strong>שלב 1: שיכון הסדרה בקטע סגור ראשוני</strong> נתון שהסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> חסומה (הגדרה 2.15), ולכן קיים <span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|a_n|\\le M\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\in [-M, M]\\)</span>.</span> נגדיר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I_1 = [A_1, B_1] = [-M, M]\\)</span>.</span> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\(I_1\\)</span> נמצאים כל איברי הסדרה, ובפרט קיימים אינסוף אינדקסים <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> המקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\in I_1\\)</span>.</span></p>\n<p><strong>שלב 2: בניית סדרת קטעים מקוננים בשיטת החצייה</strong> נבנה באינדוקציה סדרה של קטעים סגורים <span class=\"math math-inline\" dir=\"ltr\">\\(I_k=[A_k, B_k]\\)</span> המקיימת לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\in\\mathbb N\\)</span>:</span></p>\n<ol><li><span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I_{k+1}\\subseteq I_k\\)</span>,</span></li><li><span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(B_k - A_k = \\frac{2M}{2^{k-1}}\\)</span>,</span></li><li>הקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(\\{n\\in\\mathbb N \\mid a_n\\in I_k\\}\\)</span> היא אינסופית.</li></ol>\n<p>בסיס הבנייה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(k=1\\)</span>)</span> כבר מתקיים עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I_1=[-M,M]\\)</span>,</span> שאורכו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2M\\)</span>.</span> בצעד הבנייה, נניח שנבנה הקטע <span class=\"math math-inline\" dir=\"ltr\">\\(I_k=[A_k, B_k]\\)</span> כך שהקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(\\{n\\in\\mathbb N \\mid a_n\\in I_k\\}\\)</span> אינסופית. נסמן את נקודת האמצע <span class=\"math math-inline\" dir=\"ltr\">\\(m_k=\\frac{A_k+B_k}{2}\\)</span> ונביט בשני החצאים הסגורים <span class=\"math math-inline\" dir=\"ltr\">\\([A_k, m_k]\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([m_k, B_k]\\)</span>.</span></span> מאחר ש-</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\{n\\in\\mathbb N \\mid a_n\\in I_k\\} = \\{n\\in\\mathbb N \\mid a_n\\in [A_k,m_k]\\} \\cup \\{n\\in\\mathbb N \\mid a_n\\in [m_k,B_k]\\}\\]</div>\n<p>והקבוצה שבאגף שמאל אינסופית, לא ייתכן ששתי הקבוצות באגף ימין סופיות (איחוד של שתי קבוצות סופיות הוא סופי). לכן לפחות לאחד משני החצאים יש אינסוף אינדקסים <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> בתוכו. נבחר חצי כזה להיות <span class=\"math math-inline\" dir=\"ltr\">\\(I_{k+1}=[A_{k+1}, B_{k+1}]\\)</span> (אם שניהם אינסופיים, נבחר למשל את השמאלי). בבירור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I_{k+1}\\subseteq I_k\\)</span>,</span> ובנוסף <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(B_{k+1}-A_{k+1} = \\frac{B_k-A_k}{2} = \\frac{2M}{2^k}\\)</span>.</span></p>\n<p><strong>שלב 3: הפעלת הלמה של קנטור</strong> הקטעים <span class=\"math math-inline\" dir=\"ltr\">\\(I_k=[A_k,B_k]\\)</span> הם קטעים סגורים, מקוננים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(I_{k+1}\\subseteq I_k\\)</span>),</span> ואורכם מקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{k\\to\\infty}(B_k-A_k)=\\lim_{k\\to\\infty}\\frac{2M}{2^{k-1}}=0\\]</div>\n<p>לפי טענה 2.33 ומשפט 2.18 (כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;\\frac{1}{2}&lt;1\\)</span>).</span></span> לפי הלמה של קנטור (משפט 3.22), קיימת נקודה יחידה <span class=\"math math-inline\" dir=\"ltr\">\\(L\\in\\mathbb R\\)</span> השייכת לכל הקטעים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I_k\\)</span>,</span> כלומר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\in\\mathbb N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[A_k \\le L \\le B_k.\\]</div>\n<p>מכאן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(0 \\le L - A_k \\le B_k - A_k \\to 0\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 \\le B_k - L \\le B_k - A_k \\to 0\\)</span>,</span></span> ולפי משפט הסנדוויץ׳ (משפט 2.32) מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{k\\to\\infty} A_k = L \\qquad \\text{וגם} \\qquad \\lim_{k\\to\\infty} B_k = L.\\]</div>\n<p><strong>שלב 4: בחירת תת-סדרה והתכנסותה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span></span></strong> נבחר באינדוקציה סדרת אינדקסים עולה ממש <span class=\"math math-inline\" dir=\"ltr\">\\(n_1 &lt; n_2 &lt; \\dots\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_{n_k}\\in I_k\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\in\\mathbb N\\)</span>:</span></p>\n<ul><li>עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k=1\\)</span>:</span> נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(n_1=1\\)</span> (שהרי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_1\\in I_1\\)</span>).</span></li><li>בהינתן שכבר נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n_k\\)</span>,</span> כיוון שהקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(\\{n\\in\\mathbb N \\mid a_n\\in I_{k+1}\\}\\)</span> אינסופית, קיימים בה איברים הגדולים <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(n_k\\)</span></span> (אחרת הייתה מוכלת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\{1,2,\\dots,n_k\\}\\)</span></span> הסופית). נבחר אחד מהם (למשל הקטן שבהם) להיות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n_{k+1} &gt; n_k\\)</span>,</span> ומתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{n_{k+1}}\\in I_{k+1}\\)</span>.</span></li></ul>\n<p>קיבלנו תת-סדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_{n_k})\\)</span> (הגדרה 3.24) שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(k\\in\\mathbb N\\)</span> מקיימת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{n_k}\\in[A_k, B_k]\\)</span>,</span> כלומר</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[A_k \\le a_{n_k} \\le B_k.\\]</div>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{k\\to\\infty} A_k = \\lim_{k\\to\\infty} B_k = L\\)</span>,</span></span> לפי משפט הסנדוויץ׳ (משפט 2.32) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{k\\to\\infty} a_{n_k} = L\\)</span>.</span> לפיכך <span class=\"math math-inline\" dir=\"ltr\">\\((a_{n_k})\\)</span> היא תת-סדרה מתכנסת של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span>.</span> <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>שלב 1: שיכון הסדרה בקטע סגור ראשוני</strong> נתון שהסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> חסומה (הגדרה 2.15), ולכן קיים <span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|a_n|\\le M\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\in [-M, M]\\)</span>.</span> נגדיר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I_1 = [A_1, B_1] = [-M, M]\\)</span>.</span> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\(I_1\\)</span> נמצאים כל איברי הסדרה, ובפרט קיימים אינסוף אינדקסים <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> המקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\in I_1\\)</span>.</span></p>","<p><strong>שלב 2: בניית סדרת קטעים מקוננים בשיטת החצייה</strong> נבנה באינדוקציה סדרה של קטעים סגורים <span class=\"math math-inline\" dir=\"ltr\">\\(I_k=[A_k, B_k]\\)</span> המקיימת לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\in\\mathbb N\\)</span>:</span></p>\n<ol><li><span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I_{k+1}\\subseteq I_k\\)</span>,</span></li><li><span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(B_k - A_k = \\frac{2M}{2^{k-1}}\\)</span>,</span></li><li>הקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(\\{n\\in\\mathbb N \\mid a_n\\in I_k\\}\\)</span> היא אינסופית.</li></ol>\n<p>בסיס הבנייה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(k=1\\)</span>)</span> כבר מתקיים עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I_1=[-M,M]\\)</span>,</span> שאורכו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2M\\)</span>.</span> בצעד הבנייה, נניח שנבנה הקטע <span class=\"math math-inline\" dir=\"ltr\">\\(I_k=[A_k, B_k]\\)</span> כך שהקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(\\{n\\in\\mathbb N \\mid a_n\\in I_k\\}\\)</span> אינסופית. נסמן את נקודת האמצע <span class=\"math math-inline\" dir=\"ltr\">\\(m_k=\\frac{A_k+B_k}{2}\\)</span> ונביט בשני החצאים הסגורים <span class=\"math math-inline\" dir=\"ltr\">\\([A_k, m_k]\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([m_k, B_k]\\)</span>.</span></span> מאחר ש-</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\{n\\in\\mathbb N \\mid a_n\\in I_k\\} = \\{n\\in\\mathbb N \\mid a_n\\in [A_k,m_k]\\} \\cup \\{n\\in\\mathbb N \\mid a_n\\in [m_k,B_k]\\}\\]</div>\n<p>והקבוצה שבאגף שמאל אינסופית, לא ייתכן ששתי הקבוצות באגף ימין סופיות (איחוד של שתי קבוצות סופיות הוא סופי). לכן לפחות לאחד משני החצאים יש אינסוף אינדקסים <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> בתוכו. נבחר חצי כזה להיות <span class=\"math math-inline\" dir=\"ltr\">\\(I_{k+1}=[A_{k+1}, B_{k+1}]\\)</span> (אם שניהם אינסופיים, נבחר למשל את השמאלי). בבירור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I_{k+1}\\subseteq I_k\\)</span>,</span> ובנוסף <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(B_{k+1}-A_{k+1} = \\frac{B_k-A_k}{2} = \\frac{2M}{2^k}\\)</span>.</span></p>","<p><strong>שלב 3: הפעלת הלמה של קנטור</strong> הקטעים <span class=\"math math-inline\" dir=\"ltr\">\\(I_k=[A_k,B_k]\\)</span> הם קטעים סגורים, מקוננים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(I_{k+1}\\subseteq I_k\\)</span>),</span> ואורכם מקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{k\\to\\infty}(B_k-A_k)=\\lim_{k\\to\\infty}\\frac{2M}{2^{k-1}}=0\\]</div>\n<p>לפי טענה 2.33 ומשפט 2.18 (כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;\\frac{1}{2}&lt;1\\)</span>).</span></span> לפי הלמה של קנטור (משפט 3.22), קיימת נקודה יחידה <span class=\"math math-inline\" dir=\"ltr\">\\(L\\in\\mathbb R\\)</span> השייכת לכל הקטעים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I_k\\)</span>,</span> כלומר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\in\\mathbb N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[A_k \\le L \\le B_k.\\]</div>\n<p>מכאן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(0 \\le L - A_k \\le B_k - A_k \\to 0\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 \\le B_k - L \\le B_k - A_k \\to 0\\)</span>,</span></span> ולפי משפט הסנדוויץ׳ (משפט 2.32) מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{k\\to\\infty} A_k = L \\qquad \\text{וגם} \\qquad \\lim_{k\\to\\infty} B_k = L.\\]</div>","<p><strong>שלב 4: בחירת תת-סדרה והתכנסותה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span></span></strong> נבחר באינדוקציה סדרת אינדקסים עולה ממש <span class=\"math math-inline\" dir=\"ltr\">\\(n_1 &lt; n_2 &lt; \\dots\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_{n_k}\\in I_k\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\in\\mathbb N\\)</span>:</span></p>\n<ul><li>עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k=1\\)</span>:</span> נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(n_1=1\\)</span> (שהרי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_1\\in I_1\\)</span>).</span></li><li>בהינתן שכבר נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n_k\\)</span>,</span> כיוון שהקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(\\{n\\in\\mathbb N \\mid a_n\\in I_{k+1}\\}\\)</span> אינסופית, קיימים בה איברים הגדולים <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(n_k\\)</span></span> (אחרת הייתה מוכלת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\{1,2,\\dots,n_k\\}\\)</span></span> הסופית). נבחר אחד מהם (למשל הקטן שבהם) להיות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n_{k+1} &gt; n_k\\)</span>,</span> ומתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{n_{k+1}}\\in I_{k+1}\\)</span>.</span></li></ul>\n<p>קיבלנו תת-סדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_{n_k})\\)</span> (הגדרה 3.24) שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(k\\in\\mathbb N\\)</span> מקיימת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{n_k}\\in[A_k, B_k]\\)</span>,</span> כלומר</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[A_k \\le a_{n_k} \\le B_k.\\]</div>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{k\\to\\infty} A_k = \\lim_{k\\to\\infty} B_k = L\\)</span>,</span></span> לפי משפט הסנדוויץ׳ (משפט 2.32) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{k\\to\\infty} a_{n_k} = L\\)</span>.</span> לפיכך <span class=\"math math-inline\" dir=\"ltr\">\\((a_{n_k})\\)</span> היא תת-סדרה מתכנסת של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span>.</span> <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות שכדאי להימנע מהן</p><div class=\"callout-body\"><ul><li>להגיד שבכל קטע יש &quot;אינסוף ערכים של <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span>&quot; במקום &quot;אינסוף אינדקסים <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\in I_k\\)</span>&quot;: בסדרה קבועה <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=5\\)</span> יש רק ערך אחד <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(5\\)</span>),</span> אבל אינסוף אינדקסים! ההקפדה על <em>אינסוף אינדקסים</em> מבטיחה שאפשר להמשיך לבחור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n_{k+1}&gt;n_k\\)</span>.</span></li><li>לשכוח לבנות אינדקסים עולים ממש <span class=\"math math-inline\" dir=\"ltr\">\\(n_1 &lt; n_2 &lt; \\dots\\)</span> ולבחור סתם <span class=\"math math-inline\" dir=\"ltr\">\\(a_{n_k}\\in I_k\\)</span> בלי לוודא שמתקבלת תת-סדרה אמיתית.</li></ul></div></div>"}],"similar":"<p><strong>שאלות דומות</strong>: <a href=\"#/exams/36/q1\">2025ב · מועד 81, שאלה 1</a>, <a href=\"#/exams/38/q1\">2025ב · מועד 96, שאלה 1</a>, <a href=\"#/exams/44/q6\">2026ב · מועד 97, שאלה 6</a></p>","mc":null},"2":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p><strong>א.</strong> (10 נק׳) הוכיחו את משפט 2.12: אם סדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> מתכנסת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\)</span></span> וגם <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(L_2\\)</span></span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_1=L_2\\)</span>.</span></p>\n<p><strong>ב.</strong> (15 נק׳) תהי</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=\\begin{cases} e^{-\\frac{1}{x^2}} &amp; x\\ne 0 \\\\ 0 &amp; x=0 \\end{cases}.\\]</div>\n<p>הוכיחו <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></span> הקפידו לנמק כל שלב בחישובים.</p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">סדרה אינה יכולה להתקרב ללא הגבלה לשני יעדים שונים בו־זמנית, כי מאינדקס מסוים היא הייתה צריכה להיות בתוך שתי סביבות זרות שלא נפגשות.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: סדרה אינה יכולה להתקרב ללא הגבלה לשני יעדים שונים בו־זמנית, כי מאינדקס מסוים היא הייתה צריכה להיות בתוך שתי סביבות זרות שלא נפגשות.</p>\n<p><strong>תמונה בראש</strong>: נניח ששני שערים עומדים במרחק <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> מטרים זה מזה, והכדור חייב להתקרב בסופו של דבר למרחק הקטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> מטר משניהם יחד. אין נקודה על המגרש שרחוקה פחות ממטר גם <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\)</span></span> וגם <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(L_2\\)</span></span> אם המרחק ביניהם הוא <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> מטרים — ולכן שני היעדים חייבים להיות אותו מקום!</p>\n<p><strong>עם מספרים</strong>: אם <span class=\"math math-inline\" dir=\"ltr\">\\(L_1=3\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_2=5\\)</span>,</span></span> המרחק ביניהם הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>,</span> אז לוקחים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\frac{|3-5|}{2}=1\\)</span>.</span> לא יכול להיות מספר <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> שגם קרוב <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span></span> בפחות <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> (כלומר בתחום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((2,4)\\)</span>)</span> וגם קרוב <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(5\\)</span></span> בפחות <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> (בתחום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((4,6)\\)</span>)</span> — כי הקטעים לא נפגשים!</p>\n<p><strong>מושגים</strong>:</p>\n<ul><li><strong>גבול של סדרה (הגדרה 2.9)</strong>: לכל רדיוס <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span> יש אינדקס <span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span> שאחריו כל איברי הסדרה רחוקים <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span></span> בפחות <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>.</span></span></li><li><strong>אי־שוויון המשולש (טענה 1.49)</strong>: המרחק הישיר בין שתי נקודות אינו גדול מסכום המרחקים דרך נקודה שלישית: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|L_1-L_2|\\le |L_1-a_n|+|a_n-L_2|\\)</span>.</span></li></ul></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><figure class=\"demo\" id=\"demo-epsilon-n\" data-demo=\"epsilon-n\"><noscript><p>ההמחשה האינטראקטיבית דורשת JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: איך תופסים סתירה אם $L_1\\ne L_2$?","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: איך תופסים סתירה אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\ne L_2\\)</span>?</span></p><div class=\"callout-body\"><p>הניחו בשלילה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\ne L_2\\)</span>,</span> ושימו לב שהמרחק ביניהם <span class=\"math math-inline\" dir=\"ltr\">\\(|L_1-L_2|\\)</span> הוא חיובי ממש. קחו רדיוס שהוא בדיוק מחצית מהמרחק הזה: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon = \\frac{|L_1-L_2|}{2} &gt; 0\\)</span>.</span></p></div></div>"},{"title":"רמז 2: איך בוחרים $n$ אחד שמתאים לשני הגבולות?","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: איך בוחרים <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> אחד שמתאים לשני הגבולות?</p><div class=\"callout-body\"><p>הגדרה 2.9 תיתן <span class=\"math math-inline\" dir=\"ltr\">\\(N_1\\)</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(N_2\\)</span></span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_2\\)</span>.</span> אם בוחרים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n &gt; \\max\\{N_1, N_2\\}\\)</span>,</span> שתי הקרבות מתקיימות עבור אותו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span>,</span> ואי-שוויון המשולש ייתן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|L_1-L_2| &lt; |L_1-L_2|\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">תוכנית ההוכחה</p><div class=\"callout-body\"><ol><li>נניח בשלילה כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\ne L_2\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\frac{|L_1-L_2|}{2}&gt;0\\)</span>.</span></li><li>נפעיל את הגדרה 2.9 פעמיים (עבור <span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\)</span> ועבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_2\\)</span>)</span> עם אותו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>,</span> ונקבל <span class=\"math math-inline\" dir=\"ltr\">\\(N_1\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(N_2\\)</span>.</span></span></li><li>נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;\\max\\{N_1,N_2\\}\\)</span> ונשתמש באי-שוויון המשולש (טענה 1.49) על <span class=\"math math-inline\" dir=\"ltr\">\\(|L_1-L_2|\\)</span> דרך <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> כדי לקבל סתירה.</li></ol></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון</p><div class=\"callout-body\"><p><strong>שלב 1: הנחה בשלילה ובחירת <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span> מתאים</strong> נניח בשלילה כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\ne L_2\\)</span>.</span> מאחר ששני המספרים שונים, המרחק ביניהם חיובי ממש, ולכן מותר לבחור</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\varepsilon = \\frac{|L_1 - L_2|}{2} &gt; 0.\\]</div>\n<p><strong>שלב 2: שימוש בהגדרת הגבול עבור <span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\)</span> ועבור <span class=\"math math-inline\" dir=\"ltr\">\\(L_2\\)</span></strong></p>\n<ul><li>נתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} a_n = L_1\\)</span>,</span> ולכן לפי הגדרה 2.9 קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N_1\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-L_1|&lt;\\varepsilon\\)</span>.</span></li><li>נתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} a_n = L_2\\)</span>,</span> ולכן לפי הגדרה 2.9 קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N_2\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_2\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-L_2|&lt;\\varepsilon\\)</span>.</span></li></ul>\n<p>נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(N = \\max\\{N_1, N_2\\}\\)</span> ונבחר אינדקס טבעי <span class=\"math math-inline\" dir=\"ltr\">\\(n &gt; N\\)</span> (למשל <span class=\"math math-inline\" dir=\"ltr\">\\(n=\\max\\{N_1,N_2\\}+1\\)</span> אם <span class=\"math math-inline\" dir=\"ltr\">\\(N_1,N_2\\)</span> טבעיים, או לפי תכונת ארכימדס משפט 1.60). מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_1\\)</span></span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_2\\)</span>,</span> מתקיימים שני האי-שוויונות יחד:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|a_n - L_1| &lt; \\varepsilon \\qquad \\text{וגם} \\qquad |a_n - L_2| &lt; \\varepsilon.\\]</div>\n<p><strong>שלב 3: קבלת סתירה מאי-שוויון המשולש</strong> לפי אי-שוויון המשולש (טענה 1.49):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|L_1 - L_2| = |(L_1 - a_n) + (a_n - L_2)| \\le |L_1 - a_n| + |a_n - L_2| = |a_n - L_1| + |a_n - L_2|.\\]</div>\n<p>מהבחירה של <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> נובע</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|L_1 - L_2| &lt; \\varepsilon + \\varepsilon = 2\\cdot \\frac{|L_1-L_2|}{2} = |L_1 - L_2|,\\]</div>\n<p>כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|L_1-L_2| &lt; |L_1-L_2|\\)</span>,</span> שזו סתירה. לכן ההנחה שגויה, ומתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_1 = L_2\\)</span>.</span> <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>שלב 1: הנחה בשלילה ובחירת <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span> מתאים</strong> נניח בשלילה כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\ne L_2\\)</span>.</span> מאחר ששני המספרים שונים, המרחק ביניהם חיובי ממש, ולכן מותר לבחור</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\varepsilon = \\frac{|L_1 - L_2|}{2} &gt; 0.\\]</div>","<p><strong>שלב 2: שימוש בהגדרת הגבול עבור <span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\)</span> ועבור <span class=\"math math-inline\" dir=\"ltr\">\\(L_2\\)</span></strong></p>\n<ul><li>נתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} a_n = L_1\\)</span>,</span> ולכן לפי הגדרה 2.9 קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N_1\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-L_1|&lt;\\varepsilon\\)</span>.</span></li><li>נתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} a_n = L_2\\)</span>,</span> ולכן לפי הגדרה 2.9 קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N_2\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_2\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-L_2|&lt;\\varepsilon\\)</span>.</span></li></ul>\n<p>נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(N = \\max\\{N_1, N_2\\}\\)</span> ונבחר אינדקס טבעי <span class=\"math math-inline\" dir=\"ltr\">\\(n &gt; N\\)</span> (למשל <span class=\"math math-inline\" dir=\"ltr\">\\(n=\\max\\{N_1,N_2\\}+1\\)</span> אם <span class=\"math math-inline\" dir=\"ltr\">\\(N_1,N_2\\)</span> טבעיים, או לפי תכונת ארכימדס משפט 1.60). מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_1\\)</span></span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_2\\)</span>,</span> מתקיימים שני האי-שוויונות יחד:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|a_n - L_1| &lt; \\varepsilon \\qquad \\text{וגם} \\qquad |a_n - L_2| &lt; \\varepsilon.\\]</div>","<p><strong>שלב 3: קבלת סתירה מאי-שוויון המשולש</strong> לפי אי-שוויון המשולש (טענה 1.49):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|L_1 - L_2| = |(L_1 - a_n) + (a_n - L_2)| \\le |L_1 - a_n| + |a_n - L_2| = |a_n - L_1| + |a_n - L_2|.\\]</div>\n<p>מהבחירה של <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> נובע</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|L_1 - L_2| &lt; \\varepsilon + \\varepsilon = 2\\cdot \\frac{|L_1-L_2|}{2} = |L_1 - L_2|,\\]</div>\n<p>כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|L_1-L_2| &lt; |L_1-L_2|\\)</span>,</span> שזו סתירה. לכן ההנחה שגויה, ומתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_1 = L_2\\)</span>.</span> <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות שכדאי להימנע מהן</p><div class=\"callout-body\"><ul><li>לא לבחור <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;\\max\\{N_1,N_2\\}\\)</span> ולהשאיר <span class=\"math math-inline\" dir=\"ltr\">\\(n_1&gt;N_1\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(n_2&gt;N_2\\)</span></span> שונים — אי אפשר להפעיל את אי-שוויון המשולש על <span class=\"math math-inline\" dir=\"ltr\">\\(|L_1-L_2|\\)</span> אם לא משתמשים באותו איבר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span>!</span></li><li>לשכוח להסביר למה <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\frac{|L_1-L_2|}{2}&gt;0\\)</span> (כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\ne L_2\\)</span>).</span></li></ul></div></div>"},{"label":"ב","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">בכל נקודה שונה מאפס <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מורכבת מפונקציות רגילות וחלקות, ובנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> היא נעשית כל כך שטוחה שהשיפוע <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> הוא <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> ואפילו השיפועים מסביב מתקרבים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: בכל נקודה שונה מאפס <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מורכבת מפונקציות רגילות וחלקות, ובנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> היא נעשית כל כך שטוחה שהשיפוע <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> הוא <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> ואפילו השיפועים מסביב מתקרבים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p>\n<p><strong>תמונה בראש</strong>: <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> מתקרב לאפס, <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{x^2}\\)</span> מזנק למעלה, ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(e^{-1/x^2}=\\frac{1}{e^{1/x^2}}\\)</span> צונח לאפס מהר יותר מכל חזקה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>!</span> תחשבו על כביש שמתיישר במהירות אקספוננציאלית לפני כניסה לכיכר: לא רק שאין קפיצה או פינה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)=0\\)</span>),</span> אלא שגם השיפוע עצמו מתאפס בצורה חלקה ככל שמתקרבים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p>\n<p><strong>עם מספרים</strong>: כבר <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0.1\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1/x^2=100\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0.1)=e^{-100}\\approx 3.7\\cdot 10^{-44}\\)</span>!</span> אפילו מנת השינוי <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(0.1)-0}{0.1}\\)</span> היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(10e^{-100}\\approx 3.7\\cdot 10^{-43}\\)</span>,</span> והשיפוע <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{2}{0.1^3}e^{-100} = 2000e^{-100}\\)</span> כמעט אפס גמור.</p>\n<p><strong>מושגים</strong>:</p>\n<ul><li><strong>גזירות לפי הגדרה (הגדרה 7.7)</strong>: בנקודת תפר <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> אי אפשר להפעיל אוטומטית את כללי הגזירה — חייבים לחשב ישירות את גבול מנה השינוי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}\\frac{f(x)-f(0)}{x-0}\\)</span>.</span></li><li><strong>רציפות של הנגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span></strong>: לאחר שמוצאים נוסחה מפורשת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>,</span> בודקים שהיא רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span></span> (כפונקציה אלמנטרית) ושהגבול שלה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span></span> שווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)=0\\)</span>.</span></span></li></ul></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;latex&quot;:&quot;f(x)=e^{-1/x^2}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;latex&quot;:&quot;g(x)=\\\\frac{2}{x^3}e^{-1/x^2}&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;latex&quot;:&quot;(0, 0)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;f(0)=f&#39;(0)=0&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: הפרידו בין $x\\ne 0$ לבין נקודת התפר $x=0$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: הפרידו בין <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> לבין נקודת התפר <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></p><div class=\"callout-body\"><p>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> הפונקציה ניתנת לביטוי אחד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^{-1/x^2}\\)</span>,</span> ולכן גזירותה והנגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=\\frac{2}{x^3}e^{-1/x^2}\\)</span> נובעות מכלל השרשרת. <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> יש להשתמש בהגדרה 7.7!</p></div></div>"},{"title":"רמז 2: החליפו משתנה כדי לחשב את שני הגבולות ב-$x\\to 0$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: החליפו משתנה כדי לחשב את שני הגבולות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span></span></p><div class=\"callout-body\"><p>בגבול <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}\\frac{e^{-1/x^2}}{x}\\)</span> ובגבול <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}\\frac{2}{x^3}e^{-1/x^2}\\)</span> קחו ערך מוחלט וסמנו <span class=\"math math-inline\" dir=\"ltr\">\\(t=\\frac{1}{|x|}\\to\\infty\\)</span> (או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u=\\frac{1}{x^2}\\to\\infty\\)</span>),</span> ואז הפעילו את כלל לופיטל (משפט 8.16) על <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{t}{e^{t^2}}\\)</span> ועל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{2t^3}{e^{t^2}}\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">תוכנית ההוכחה</p><div class=\"callout-body\"><ol><li>נגזור לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> לפי כלל השרשרת ונקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=\\frac{2}{x^3}e^{-1/x^2}\\)</span>,</span> שברור כי היא רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\setminus\\{0\\}\\)</span></span> כאריתמטיקה והרכבה של אלמנטריות.</li><li>נוכיח גבול עזר בלופיטל: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{t\\to\\infty}\\frac{t}{e^{t^2}}=0\\)</span>,</span> וממנו נגזור מיד בעזרת לופיטל פעם נוספת כי גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{t\\to\\infty}\\frac{2t^3}{e^{t^2}}=0\\)</span>.</span></li><li><span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> נבדוק ישירות את הגדרת הנגזרת (הגדרה 7.7): בעזרת הצבת הרכבה <span class=\"math math-inline\" dir=\"ltr\">\\(t=\\frac{1}{|x|}\\to\\infty\\)</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left|\\frac{f(x)-f(0)}{x-0}\\right|=\\frac{t}{e^{t^2}}\\to 0\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)=0\\)</span>.</span></li><li>לרציפות <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> נראה כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f'(x)| = \\frac{2t^3}{e^{t^2}} \\to 0 = f'(0)\\)</span>,</span> ומכאן <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> ולכן בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></li></ol></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון</p><div class=\"callout-body\"><p><strong>שלב 1: גזירות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span></span> ונוסחת הנגזרת שם</strong> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=e^{-1/x^2}\\)</span>.</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(u(x)=-\\frac{1}{x^2}=-x^{-2}\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\setminus\\{0\\}\\)</span> (משפטים 7.15, 7.16/7.20) ונגזרתה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u'(x)=\\frac{2}{x^3}\\)</span>.</span> הפונקציה המעריכית <span class=\"math math-inline\" dir=\"ltr\">\\(e^u\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> ונגזרתה <span class=\"math math-inline\" dir=\"ltr\">\\(e^u\\)</span> (משפט 7.30). מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=e^{-1/x^2}\\)</span></span> תקפה בסביבה של כל <span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\ne 0\\)</span> שאינה כוללת את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> לפי כלל השרשרת (משפט 7.21) <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> ונגזרתה היא</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x) = e^{-1/x^2}\\cdot\\frac{2}{x^3} = \\frac{2}{x^3}e^{-1/x^2} \\qquad (x\\ne 0).\\]</div>\n<p><strong>שלב 2: חישוב שני גבולות עזר באינסוף</strong> נחשב תחילה את <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{t\\to\\infty}\\frac{t}{e^{t^2}}\\)</span> בעזרת כלל לופיטל לצורת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\infty}{\\infty}\\)</span> באינסוף (משפט 8.16):</p>\n<ul><li>המונה <span class=\"math math-inline\" dir=\"ltr\">\\(t\\)</span> והמכנה <span class=\"math math-inline\" dir=\"ltr\">\\(e^{t^2}\\)</span> גזירים <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((1,\\infty)\\)</span>,</span></span> ושניהם שואפים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span></span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(t\\to\\infty\\)</span></span> (לפי משפט 6.9, כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t^2\\to\\infty\\)</span>).</span></span></li><li>נגזרת המכנה <span class=\"math math-inline\" dir=\"ltr\">\\((e^{t^2})' = 2te^{t^2}\\)</span> שונה מאפס לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t&gt;1\\)</span>.</span></li><li>גבול מנת הנגזרות הוא</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{t\\to\\infty}\\frac{1}{2te^{t^2}} = 0\\]</div>\n<p>(כי <span class=\"math math-inline\" dir=\"ltr\">\\(2te^{t^2}\\ge 2t\\to\\infty\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t&gt;1\\)</span>,</span></span> לפי משפט 4.53 / השוואה). לכן לפי משפט 8.16 מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{t\\to\\infty}\\frac{t}{e^{t^2}} = 0.\\]</div>\n<p>כעת נחשב באותו אופן את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{t\\to\\infty}\\frac{2t^3}{e^{t^2}}\\)</span>:</span> שוב המונה והמכנה שואפים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span></span> וגזירים <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((1,\\infty)\\)</span></span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((e^{t^2})'=2te^{t^2}\\ne 0\\)</span>.</span> גבול מנת הנגזרות הוא</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{t\\to\\infty}\\frac{6t^2}{2te^{t^2}} = 3\\lim_{t\\to\\infty}\\frac{t}{e^{t^2}} = 3\\cdot 0 = 0\\]</div>\n<p>(לפי הגבול שכבר הוכחנו). לכן לפי כלל לופיטל (משפט 8.16),</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{t\\to\\infty}\\frac{2t^3}{e^{t^2}} = 0.\\]</div>\n<p><strong>שלב 3: גזירות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> לפי הגדרה</strong> נבדוק את קיום הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}\\frac{f(x)-f(0)}{x-0}\\)</span> (הגדרה 7.7). לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span>,</span> ולכן</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\left|\\frac{f(x)-f(0)}{x-0}\\right| = \\frac{e^{-1/x^2}}{|x|} = \\frac{1/|x|}{e^{(1/|x|)^2}}.\\]</div>\n<p><span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span></span> (בסביבה נקובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>),</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}|x|=0\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x|&gt;0\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}\\frac{1}{|x|}=\\infty\\)</span> (משפט 4.53). מהגבול הראשון של שלב 2 וגבול של הרכבה (משפט 4.39 המורחב לאינסוף, או אפיון היינה: לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\to 0\\)</span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\ne 0\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(t_n=\\frac{1}{|x_n|}\\to\\infty\\)</span> ומכאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{t_n}{e^{t_n^2}}\\to 0\\)</span>),</span> נובע</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0}\\left|\\frac{f(x)-f(0)}{x-0}\\right| = 0.\\]</div>\n<p>מאי-שוויון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|g(x)|\\ge 0\\)</span>,</span> לפי משפט הסנדוויץ׳ <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(-|g(x)|\\le g(x)\\le |g(x)|\\)</span>,</span> משפט 4.43) מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(0) = \\lim_{x\\to 0}\\frac{f(x)-f(0)}{x-0} = 0.\\]</div>\n<p>בסיכום שלבים 1 ו-3, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> ומתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x)=\\begin{cases}\\frac{2}{x^3}e^{-1/x^2} &amp; x\\ne 0 \\\\ 0 &amp; x=0\\end{cases}.\\]</div>\n<p><strong>שלב 4: הוכחת רציפות <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></strong></p>\n<ul><li>לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\ne 0\\)</span>:</span> בסביבה שאינה כוללת את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=\\frac{2}{x^3}e^{-1/x^2}\\)</span> היא מכפלה והרכבה של פונקציות רציפות <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{2}{x^3}\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac{1}{x^2}\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^u\\)</span>,</span></span> לפי משפטים 5.11, 5.12, 5.15, 6.9), ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> רציפה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\ne 0\\)</span>.</span></li><li>בנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0=0\\)</span>:</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>,</span> בהצבת <span class=\"math math-inline\" dir=\"ltr\">\\(t=\\frac{1}{|x|}\\)</span> מתקיים</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f'(x)| = \\frac{2}{|x|^3}e^{-1/x^2} = \\frac{2t^3}{e^{t^2}}.\\]</div>\n<p>מאחר שכאשר <span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t=\\frac{1}{|x|}\\to\\infty\\)</span>,</span> מהגבול השני של שלב 2 נובע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}|f'(x)| = 0\\)</span>,</span> וכמו קודם לפי הסנדוויץ׳ <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0} f'(x) = 0 = f'(0)\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> רציפה גם <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>,</span></span> ומכאן <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> רציפה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span> <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>שלב 1: גזירות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span></span> ונוסחת הנגזרת שם</strong> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=e^{-1/x^2}\\)</span>.</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(u(x)=-\\frac{1}{x^2}=-x^{-2}\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\setminus\\{0\\}\\)</span> (משפטים 7.15, 7.16/7.20) ונגזרתה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u'(x)=\\frac{2}{x^3}\\)</span>.</span> הפונקציה המעריכית <span class=\"math math-inline\" dir=\"ltr\">\\(e^u\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> ונגזרתה <span class=\"math math-inline\" dir=\"ltr\">\\(e^u\\)</span> (משפט 7.30). מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=e^{-1/x^2}\\)</span></span> תקפה בסביבה של כל <span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\ne 0\\)</span> שאינה כוללת את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> לפי כלל השרשרת (משפט 7.21) <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> ונגזרתה היא</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x) = e^{-1/x^2}\\cdot\\frac{2}{x^3} = \\frac{2}{x^3}e^{-1/x^2} \\qquad (x\\ne 0).\\]</div>","<p><strong>שלב 2: חישוב שני גבולות עזר באינסוף</strong> נחשב תחילה את <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{t\\to\\infty}\\frac{t}{e^{t^2}}\\)</span> בעזרת כלל לופיטל לצורת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\infty}{\\infty}\\)</span> באינסוף (משפט 8.16):</p>\n<ul><li>המונה <span class=\"math math-inline\" dir=\"ltr\">\\(t\\)</span> והמכנה <span class=\"math math-inline\" dir=\"ltr\">\\(e^{t^2}\\)</span> גזירים <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((1,\\infty)\\)</span>,</span></span> ושניהם שואפים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span></span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(t\\to\\infty\\)</span></span> (לפי משפט 6.9, כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t^2\\to\\infty\\)</span>).</span></span></li><li>נגזרת המכנה <span class=\"math math-inline\" dir=\"ltr\">\\((e^{t^2})' = 2te^{t^2}\\)</span> שונה מאפס לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t&gt;1\\)</span>.</span></li><li>גבול מנת הנגזרות הוא</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{t\\to\\infty}\\frac{1}{2te^{t^2}} = 0\\]</div>\n<p>(כי <span class=\"math math-inline\" dir=\"ltr\">\\(2te^{t^2}\\ge 2t\\to\\infty\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t&gt;1\\)</span>,</span></span> לפי משפט 4.53 / השוואה). לכן לפי משפט 8.16 מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{t\\to\\infty}\\frac{t}{e^{t^2}} = 0.\\]</div>\n<p>כעת נחשב באותו אופן את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{t\\to\\infty}\\frac{2t^3}{e^{t^2}}\\)</span>:</span> שוב המונה והמכנה שואפים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span></span> וגזירים <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((1,\\infty)\\)</span></span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((e^{t^2})'=2te^{t^2}\\ne 0\\)</span>.</span> גבול מנת הנגזרות הוא</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{t\\to\\infty}\\frac{6t^2}{2te^{t^2}} = 3\\lim_{t\\to\\infty}\\frac{t}{e^{t^2}} = 3\\cdot 0 = 0\\]</div>\n<p>(לפי הגבול שכבר הוכחנו). לכן לפי כלל לופיטל (משפט 8.16),</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{t\\to\\infty}\\frac{2t^3}{e^{t^2}} = 0.\\]</div>","<p><strong>שלב 3: גזירות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> לפי הגדרה</strong> נבדוק את קיום הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}\\frac{f(x)-f(0)}{x-0}\\)</span> (הגדרה 7.7). לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span>,</span> ולכן</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\left|\\frac{f(x)-f(0)}{x-0}\\right| = \\frac{e^{-1/x^2}}{|x|} = \\frac{1/|x|}{e^{(1/|x|)^2}}.\\]</div>\n<p><span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span></span> (בסביבה נקובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>),</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}|x|=0\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x|&gt;0\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}\\frac{1}{|x|}=\\infty\\)</span> (משפט 4.53). מהגבול הראשון של שלב 2 וגבול של הרכבה (משפט 4.39 המורחב לאינסוף, או אפיון היינה: לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\to 0\\)</span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\ne 0\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(t_n=\\frac{1}{|x_n|}\\to\\infty\\)</span> ומכאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{t_n}{e^{t_n^2}}\\to 0\\)</span>),</span> נובע</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0}\\left|\\frac{f(x)-f(0)}{x-0}\\right| = 0.\\]</div>\n<p>מאי-שוויון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|g(x)|\\ge 0\\)</span>,</span> לפי משפט הסנדוויץ׳ <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(-|g(x)|\\le g(x)\\le |g(x)|\\)</span>,</span> משפט 4.43) מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(0) = \\lim_{x\\to 0}\\frac{f(x)-f(0)}{x-0} = 0.\\]</div>\n<p>בסיכום שלבים 1 ו-3, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> ומתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x)=\\begin{cases}\\frac{2}{x^3}e^{-1/x^2} &amp; x\\ne 0 \\\\ 0 &amp; x=0\\end{cases}.\\]</div>","<p><strong>שלב 4: הוכחת רציפות <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></strong></p>\n<ul><li>לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\ne 0\\)</span>:</span> בסביבה שאינה כוללת את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=\\frac{2}{x^3}e^{-1/x^2}\\)</span> היא מכפלה והרכבה של פונקציות רציפות <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{2}{x^3}\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac{1}{x^2}\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^u\\)</span>,</span></span> לפי משפטים 5.11, 5.12, 5.15, 6.9), ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> רציפה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\ne 0\\)</span>.</span></li><li>בנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0=0\\)</span>:</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>,</span> בהצבת <span class=\"math math-inline\" dir=\"ltr\">\\(t=\\frac{1}{|x|}\\)</span> מתקיים</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f'(x)| = \\frac{2}{|x|^3}e^{-1/x^2} = \\frac{2t^3}{e^{t^2}}.\\]</div>\n<p>מאחר שכאשר <span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t=\\frac{1}{|x|}\\to\\infty\\)</span>,</span> מהגבול השני של שלב 2 נובע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}|f'(x)| = 0\\)</span>,</span> וכמו קודם לפי הסנדוויץ׳ <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0} f'(x) = 0 = f'(0)\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> רציפה גם <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>,</span></span> ומכאן <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> רציפה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span> <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות שכדאי להימנע מהן</p><div class=\"callout-body\"><ul><li>לנסות להוכיח <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> על ידי גבול הנגזרות <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0} f'(x)=0\\)</span> בלי לציין ולנמק קודם <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>!</span></span> (למעשה משפט 8.11/לגראנז׳ יכולים להסיק גזירות רק אם מראים קודם <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>:</span></span> אילו הגדרנו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=1\\)</span>,</span> עדיין <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0} f'(x)=0\\)</span>,</span> אבל <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> לא הייתה רציפה ולא גזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>!</span></span> בדיקה ישירה של <span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)\\)</span> מהגדרה 7.7 מונעת את הטעות לחלוטין.)</li><li>לעשות הצבה לא תקפה או לשכוח לבדוק שתנאי כלל לופיטל מתקיימים (בפרט למה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{|x|}\\to\\infty\\)</span> <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span>,</span></span> ולמה המכנה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2te^{t^2}\\ne 0\\)</span>).</span></li></ul></div></div>"}],"similar":"<p><strong>שאלות דומות</strong>: <a href=\"#/exams/31/q2\">2024א · מועד 96, שאלה 2</a> (סעיף א), <a href=\"#/exams/45/q6\">2026ג · מועד 83, שאלה 6</a> (סעיף א)</p>","mc":null,"options":["א","ב"]},"3":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>תהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=x+\\frac{2}{e^x}-1\\)</span>.</span></p>\n<p><strong>(1).</strong> הוכיחו שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)&lt;x\\)</span>.</span></p>\n<p><strong>(2).</strong> הוכיחו שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)&gt;\\ln 2\\)</span>.</span></p>\n<p><strong>(3).</strong> תהי <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> סדרה הנתונה ע״י: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_1=1\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+1}=g(x_n)\\)</span>.</span> הוכיחו כי <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> מתכנסת וחשבו את גבולה.</p></div></div>","parts":[{"label":"(1)","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כאשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span>,</span> השבר <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{2}{e^x}\\)</span> קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> ולכן הוספת <span class=\"math math-inline\" dir=\"ltr\">\\(\\left(\\frac{2}{e^x}-1\\right)\\)</span> אל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> מקטינה אותו!</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כאשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span>,</span> השבר <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{2}{e^x}\\)</span> קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> ולכן הוספת <span class=\"math math-inline\" dir=\"ltr\">\\(\\left(\\frac{2}{e^x}-1\\right)\\)</span> אל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> מקטינה אותו!</p>\n<p><strong>תמונה בראש</strong>: הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)\\)</span> לוקחת את <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> ומוסיפה לו תיקון של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{2}{e^x}-1\\)</span>.</span> בגלל <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e^x\\)</span></span> עולה, בדיוק <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=\\ln 2\\)</span></span> הערך של <span class=\"math math-inline\" dir=\"ltr\">\\(e^x\\)</span> שווה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span></span> והתיקון מתאפס <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(g(\\ln 2)=\\ln 2\\)</span>).</span> מעבר <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span>,</span></span> המכנה <span class=\"math math-inline\" dir=\"ltr\">\\(e^x\\)</span> גדל מעל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>,</span> השבר <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{2}{e^x}\\)</span> יורד מתחת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> והתיקון נהיה שלילי!</p>\n<p><strong>עם מספרים</strong>: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2 \\approx 0.693\\)</span>.</span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1 &gt; \\ln 2\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^1 \\approx 2.718 &gt; 2\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(1)=1+\\frac{2}{e}-1 = \\frac{2}{e}\\approx 0.736 &lt; 1\\)</span>.</span></p>\n<p><strong>מושגים</strong>:</p>\n<ul><li><strong>מונוטוניות של <span class=\"math math-inline\" dir=\"ltr\">\\(e^x\\)</span> (משפט 6.9)</strong>: הפונקציה המעריכית <span class=\"math math-inline\" dir=\"ltr\">\\(e^x\\)</span> עולה ממש בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span> וההפוכה שלה היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln x\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^{\\ln 2}=2\\)</span>.</span></li></ul></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;latex&quot;:&quot;g(x)=x+2e^{-x}-1&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;latex&quot;:&quot;y=x&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;latex&quot;:&quot;x=\\\\ln(2)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;latex&quot;:&quot;(0.6931, 0.6931)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;(ln 2, ln 2)&quot;},{&quot;latex&quot;:&quot;(1, 0.7358)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;g(1) &lt; 1&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: בצעו אלגברה פשוטה על $g(x) - x$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: בצעו אלגברה פשוטה על <span class=\"math math-inline\" dir=\"ltr\">\\(g(x) - x\\)</span></p><div class=\"callout-body\"><p>למה שווה ההפרש <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)-x\\)</span>?</span> כתבו אותו וראו שמדובר בהשוואה פשוטה של <span class=\"math math-inline\" dir=\"ltr\">\\(e^x\\)</span> מול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span></p></div></div>"},{"title":"רמז 2: שימוש במונוטוניות של $e^x$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: שימוש במונוטוניות של <span class=\"math math-inline\" dir=\"ltr\">\\(e^x\\)</span></p><div class=\"callout-body\"><p>מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e^x\\)</span></span> עולה ממש (משפט 6.9), אם <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^x &gt; e^{\\ln 2} = 2\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">תוכנית ההוכחה</p><div class=\"callout-body\"><ol><li>ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span> ונסיק מעליית <span class=\"math math-inline\" dir=\"ltr\">\\(e^t\\)</span> (משפט 6.9) <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^x &gt; e^{\\ln 2} = 2\\)</span>.</span></span></li><li>נחלק <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(e^x&gt;0\\)</span></span> (טענה 1.42) כדי לקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{2}{e^x}&lt;1\\)</span>.</span></li><li>נחסר <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> ונוסיף <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> בשני האגפים לקבלת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x) = x + \\frac{2}{e^x} - 1 &lt; x\\)</span>.</span></li></ol></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון</p><div class=\"callout-body\"><p><strong>שלב 1: הערכת <span class=\"math math-inline\" dir=\"ltr\">\\(e^x\\)</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span></strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; \\ln 2\\)</span>.</span> הפונקציה המעריכית <span class=\"math math-inline\" dir=\"ltr\">\\(t\\mapsto e^t\\)</span> עולה ממש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> (משפט 6.9, שכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e&gt;1\\)</span>).</span> לכן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span></span> ומהגדרת <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln\\)</span> כהפוכה של <span class=\"math math-inline\" dir=\"ltr\">\\(e^t\\)</span> (הגדרה 6.11) מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[e^x &gt; e^{\\ln 2} = 2 &gt; 0.\\]</div>\n<p><strong>שלב 2: מעבר אל <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)&lt;x\\)</span></strong> מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^x &gt; 2 &gt; 0\\)</span>,</span></span> מחלוקה של אי-השוויון <span class=\"math math-inline\" dir=\"ltr\">\\(2 &lt; e^x\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(e^x &gt; 0\\)</span></span> מתקבל</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{2}{e^x} &lt; 1 \\implies \\frac{2}{e^x} - 1 &lt; 0.\\]</div>\n<p>נוסיף <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> לשני האגפים ונקבל</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x) = x + \\frac{2}{e^x} - 1 &lt; x.\\]</div>\n<p><span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>שלב 1: הערכת <span class=\"math math-inline\" dir=\"ltr\">\\(e^x\\)</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span></strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; \\ln 2\\)</span>.</span> הפונקציה המעריכית <span class=\"math math-inline\" dir=\"ltr\">\\(t\\mapsto e^t\\)</span> עולה ממש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> (משפט 6.9, שכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e&gt;1\\)</span>).</span> לכן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span></span> ומהגדרת <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln\\)</span> כהפוכה של <span class=\"math math-inline\" dir=\"ltr\">\\(e^t\\)</span> (הגדרה 6.11) מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[e^x &gt; e^{\\ln 2} = 2 &gt; 0.\\]</div>","<p><strong>שלב 2: מעבר אל <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)&lt;x\\)</span></strong> מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^x &gt; 2 &gt; 0\\)</span>,</span></span> מחלוקה של אי-השוויון <span class=\"math math-inline\" dir=\"ltr\">\\(2 &lt; e^x\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(e^x &gt; 0\\)</span></span> מתקבל</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{2}{e^x} &lt; 1 \\implies \\frac{2}{e^x} - 1 &lt; 0.\\]</div>\n<p>נוסיף <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> לשני האגפים ונקבל</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x) = x + \\frac{2}{e^x} - 1 &lt; x.\\]</div>\n<p><span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות שכדאי להימנע מהן</p><div class=\"callout-body\"><ul><li>לכתוב שרשרת אי-שוויונות <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)&lt;x \\iff \\dots \\iff x&gt;\\ln 2\\)</span> בלי לנסח את כיוון הגרירה מהנתון <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span> אל המסקנה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)&lt;x\\)</span> (או להשתמש בבירור בסימני שקילות).</li></ul></div></div>"},{"label":"(2)","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([\\ln 2, \\infty)\\)</span> הנגזרת של <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> חיובית, ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> עולה ממש מעל הערך ההתחלתי שלה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(\\ln 2)=\\ln 2\\)</span>.</span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([\\ln 2, \\infty)\\)</span> הנגזרת של <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> חיובית, ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> עולה ממש מעל הערך ההתחלתי שלה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(\\ln 2)=\\ln 2\\)</span>.</span></p>\n<p><strong>תמונה בראש</strong>: דמיינו מדרגה שמתחילה בדיוק בגובה <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span> בנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=\\ln 2\\)</span>.</span> כל עוד ממשיכים ימינה והנגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)=1-\\frac{2}{e^x}\\)</span> חיובית, המדרגה עולה כלפי מעלה — ולכן לעולם לא נופלת מתחת לגובה הפתיחה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span>!</span></p>\n<p><strong>עם מספרים</strong>: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(\\ln 2) = \\ln 2 + \\frac{2}{2} - 1 = \\ln 2 \\approx 0.6931\\)</span>.</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span>,</span></span> הנגזרת חיובית <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(g'(1)=1-\\frac{2}{e}\\approx 0.264 &gt; 0\\)</span>),</span> וכפי שראינו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(1)\\approx 0.7358 &gt; 0.6931 = \\ln 2\\)</span>.</span></p>\n<p><strong>מושגים</strong>:</p>\n<ul><li><strong>קריטריון מונוטוניות של נגזרת (משפט 8.18)</strong>: אם פונקציה רציפה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([a,\\infty)\\)</span> ונגזרתה חיובית ממש <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span>,</span></span> אז היא עולה ממש בכל <span class=\"math math-inline\" dir=\"ltr\">\\([a,\\infty)\\)</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)&gt;g(a)\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;a\\)</span>.</span></li></ul></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;latex&quot;:&quot;g(x)=x+2e^{-x}-1&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;latex&quot;:&quot;y=\\\\ln(2)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;latex&quot;:&quot;x=\\\\ln(2)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;latex&quot;:&quot;(0.6931, 0.6931)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;g(ln 2)=ln 2&quot;},{&quot;latex&quot;:&quot;(1, 0.7358)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;g(1) ≈ 0.736 &gt; ln 2&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: חשבו את $g(\\ln 2)$ ואת הנגזרת $g'(x)$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: חשבו את <span class=\"math math-inline\" dir=\"ltr\">\\(g(\\ln 2)\\)</span> ואת הנגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)\\)</span></p><div class=\"callout-body\"><p>למה שווה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(\\ln 2)\\)</span>?</span> ומה הסימן של <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x) = 1 - \\frac{2}{e^x}\\)</span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span>?</span></p></div></div>"},{"title":"רמז 2: שימו לב לתנאי משפט 8.18 גם בקצה $\\ln 2$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: שימו לב לתנאי משפט 8.18 גם בקצה <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span></p><div class=\"callout-body\"><p>כדי להשוות <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(\\ln 2)\\)</span>,</span> ציינו <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([\\ln 2, \\infty)\\)</span></span> (וגזירה בפנים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((\\ln 2, \\infty)\\)</span>).</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">תוכנית ההוכחה</p><div class=\"callout-body\"><ol><li>נבדוק את ערך הפונקציה בקצה: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(\\ln 2) = \\ln 2\\)</span>.</span></li><li>נגזור את <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> ונראה שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x) = 1-\\frac{2}{e^x} &gt; 0\\)</span> (כפי שהראינו בסעיף 1).</li><li>מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([\\ln 2,\\infty)\\)</span></span> ונגזרתה חיובית <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((\\ln 2,\\infty)\\)</span>,</span></span> נסיק ממשפט 8.18 <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span></span> עולה ממש בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([\\ln 2,\\infty)\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)&gt;g(\\ln 2)=\\ln 2\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span>.</span></li></ol></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון</p><div class=\"callout-body\"><p><strong>שלב 1: ערך הפונקציה בקצה <span class=\"math math-inline\" dir=\"ltr\">\\(x=\\ln 2\\)</span> וחישוב הנגזרת</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=x+2e^{-x}-1\\)</span> רציפה וגזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (משפטים 5.11, 6.9, 7.13, 7.21, 7.30), ובפרט רציפה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([\\ln 2, \\infty)\\)</span> וגזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((\\ln 2, \\infty)\\)</span>.</span></span> בקצה <span class=\"math math-inline\" dir=\"ltr\">\\(x=\\ln 2\\)</span> מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(\\ln 2) = \\ln 2 + \\frac{2}{e^{\\ln 2}} - 1 = \\ln 2 + \\frac{2}{2} - 1 = \\ln 2.\\]</div>\n<p>נגזרתה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> היא</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(x) = 1 - 2e^{-x} = 1 - \\frac{2}{e^x}.\\]</div>\n<p><strong>שלב 2: סימן הנגזרת והסקת <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)&gt;\\ln 2\\)</span></strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span>,</span> כפי שראינו בסעיף (1), מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^x &gt; e^{\\ln 2} = 2\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{2}{e^x} &lt; 1\\)</span>,</span> כלומר</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(x) = 1 - \\frac{2}{e^x} &gt; 0 \\qquad \\text{לכל } x\\in(\\ln 2, \\infty).\\]</div>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([\\ln 2, \\infty)\\)</span></span> ונגזרתה חיובית ממש בכל נקודה פנימית <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(\\ln 2, \\infty)\\)</span>,</span> לפי משפט 8.18 הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> עולה ממש בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([\\ln 2, \\infty)\\)</span>.</span> לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span> מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x) &gt; g(\\ln 2) = \\ln 2.\\]</div>\n<p><span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>שלב 1: ערך הפונקציה בקצה <span class=\"math math-inline\" dir=\"ltr\">\\(x=\\ln 2\\)</span> וחישוב הנגזרת</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=x+2e^{-x}-1\\)</span> רציפה וגזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (משפטים 5.11, 6.9, 7.13, 7.21, 7.30), ובפרט רציפה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([\\ln 2, \\infty)\\)</span> וגזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((\\ln 2, \\infty)\\)</span>.</span></span> בקצה <span class=\"math math-inline\" dir=\"ltr\">\\(x=\\ln 2\\)</span> מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(\\ln 2) = \\ln 2 + \\frac{2}{e^{\\ln 2}} - 1 = \\ln 2 + \\frac{2}{2} - 1 = \\ln 2.\\]</div>\n<p>נגזרתה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> היא</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(x) = 1 - 2e^{-x} = 1 - \\frac{2}{e^x}.\\]</div>","<p><strong>שלב 2: סימן הנגזרת והסקת <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)&gt;\\ln 2\\)</span></strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span>,</span> כפי שראינו בסעיף (1), מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^x &gt; e^{\\ln 2} = 2\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{2}{e^x} &lt; 1\\)</span>,</span> כלומר</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(x) = 1 - \\frac{2}{e^x} &gt; 0 \\qquad \\text{לכל } x\\in(\\ln 2, \\infty).\\]</div>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([\\ln 2, \\infty)\\)</span></span> ונגזרתה חיובית ממש בכל נקודה פנימית <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(\\ln 2, \\infty)\\)</span>,</span> לפי משפט 8.18 הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> עולה ממש בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([\\ln 2, \\infty)\\)</span>.</span> לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span> מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x) &gt; g(\\ln 2) = \\ln 2.\\]</div>\n<p><span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות שכדאי להימנע מהן</p><div class=\"callout-body\"><ul><li>לטעון ש-&quot;<span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=x+2e^{-x}-1 &gt; \\ln 2\\)</span> כי <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\ln 2\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(2e^{-x}&gt;0\\)</span></span>&quot; בלי לזכור שיש שם גם <span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span> (הפרש של <span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span> לבדו יכול להוריד אל מתחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span></span> אילו <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{2}{e^x}\\)</span> היה קטן מדי, לכן חייבים את הנגזרת של <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> יחד עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(\\ln 2)=\\ln 2\\)</span>!).</span></li></ul></div></div>"},{"label":"(3)","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">בגלל <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x_1=1\\)</span></span> גדול <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span>,</span></span> כל האיברים נשארים מעל <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span> (סעיף 2) ויורדים בכל צעד (סעיף 1) — סדרה יורדת וחסומה מלרע תמיד מתכנסת, ומשוואת הרקורסיה נותנת שהגבול הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span>.</span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: בגלל <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x_1=1\\)</span></span> גדול <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span>,</span></span> כל האיברים נשארים מעל <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span> (סעיף 2) ויורדים בכל צעד (סעיף 1) — סדרה יורדת וחסומה מלרע תמיד מתכנסת, ומשוואת הרקורסיה נותנת שהגבול הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span>.</span></p>\n<p><strong>תמונה בראש</strong>: תחשבו על כדור שמניחים בגובה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> מטר מעל רצפה בגובה <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2 \\approx 0.693\\)</span> מטר. סעיף (2) הוא רצפת הגנה שמבטיחה שלעולם לא יפול מתחת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span>,</span></span> וסעיף (1) אומר שבכל קפיצה הוא יורד לגובה נמוך יותר מהנוכחי. אם אתה כל הזמן יורד ויש לך רצפה מתחת לרגליים, אתה מתיישב בהכרח בגבול סופי — וכשתקע בנקודת שבת מתברר שזו בדיוק הרצפה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span>!</span></p>\n<p><strong>עם מספרים</strong>: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_1 = 1\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_2 = g(1) = \\frac{2}{e}\\approx 0.7358\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_3 = g(0.7358) \\approx 0.6940\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_4 \\approx 0.69315\\)</span>,</span> כשהיעד הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2 \\approx 0.693147\\)</span>.</span></p>\n<p><strong>מושגים</strong>:</p>\n<ul><li><strong>משפט ההתכנסות המונוטונית (משפט 3.16)</strong>: סדרה מונוטונית יורדת וחסומה מלרע מתכנסת לגבול סופי.</li><li><strong>שמירת אי־שוויונות בגבול (משפט 2.31)</strong>: אם כל איברי הסדרה גדולים <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span>,</span></span> הגבול שלה גדול או שווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span>.</span></span></li></ul></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;latex&quot;:&quot;y=\\\\ln(2)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;latex&quot;:&quot;(1, 1)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;x_1=1&quot;},{&quot;latex&quot;:&quot;(2, 0.7358)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;x_2 ≈ 0.736&quot;},{&quot;latex&quot;:&quot;(3, 0.6940)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;x_3 ≈ 0.694&quot;},{&quot;latex&quot;:&quot;(4, 0.69315)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;x_4 ≈ 0.693 (מתקרב ל-ln 2)&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: בדקו תחילה למה $x_1=1 > \\ln 2$ והשתמשו באינדוקציה לסעיף (2)","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: בדקו תחילה למה <span class=\"math math-inline\" dir=\"ltr\">\\(x_1=1 &gt; \\ln 2\\)</span> והשתמשו באינדוקציה לסעיף (2)</p><div class=\"callout-body\"><p>מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e &gt; 2\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\ln\\)</span></span> עולה ממש (משפט 6.14), מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1 = \\ln e &gt; \\ln 2\\)</span>.</span> כעת הראו באינדוקציה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x_n &gt; \\ln 2\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>.</span></p></div></div>"},{"title":"רמז 2: שלבו את סעיף (1) ואת משפט 3.16, ואז העבירו גבול","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: שלבו את סעיף (1) ואת משפט 3.16, ואז העבירו גבול</p><div class=\"callout-body\"><p><span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(x_n&gt;\\ln 2\\)</span></span> ומסעיף (1) מתקבל מיד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+1}=g(x_n) &lt; x_n\\)</span>.</span> לאחר שהראיתם שהגבול <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> קיים (משפט 3.16), עברו לגבול <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+1}=x_n+2e^{-x_n}-1\\)</span></span> בעזרת רציפות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^x\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">תוכנית ההוכחה</p><div class=\"callout-body\"><ol><li>נבדוק <span class=\"math math-inline\" dir=\"ltr\">\\(x_1=1 &gt; \\ln 2\\)</span> (כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e&gt;2\\)</span>)</span> ונוכיח באינדוקציה לפי סעיף (2) שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_n &gt; \\ln 2\\)</span>,</span> כלומר <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> חסומה מלרע <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span>.</span></span></li><li>לפי סעיף (1), מהתנאי <span class=\"math math-inline\" dir=\"ltr\">\\(x_n&gt;\\ln 2\\)</span> נובע <span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+1}=g(x_n) &lt; x_n\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>,</span> כלומר <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> יורדת ממש.</li><li>לפי משפט 3.16, <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> מתכנסת לגבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span></li><li>בעזרת עמידות הגבול <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim x_{n+1}=L\\)</span>),</span> רציפות <span class=\"math math-inline\" dir=\"ltr\">\\(e^t\\)</span> (משפט 6.9, טענה 5.4) ואריתמטיקה של גבולות נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=L+\\frac{2}{e^L}-1\\)</span>,</span> ומכאן <span class=\"math math-inline\" dir=\"ltr\">\\(e^L=2\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=\\ln 2\\)</span>.</span></span></li></ol></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון</p><div class=\"callout-body\"><p><strong>שלב 1: חסימות מלרע <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x_n &gt; \\ln 2\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>)</span></strong> נבדוק באינדוקציה על <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_n &gt; \\ln 2\\)</span>:</span></p>\n<ul><li><strong>בסיס <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(n=1\\)</span>)</span></strong>: כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e &gt; 2\\)</span></span> (כי <span class=\"math math-inline\" dir=\"ltr\">\\(e=\\lim_{n\\to\\infty}(1+\\frac{1}{n})^n\\)</span> וכל איבר <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span></span> גדול <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>)</span></span> והפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln\\)</span> עולה ממש (משפט 6.14), מתקיים</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[x_1 = 1 = \\ln e &gt; \\ln 2.\\]</div>\n<ul><li><strong>צעד</strong>: נניח כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_n &gt; \\ln 2\\)</span>.</span> אז לפי סעיף (2), מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+1} = g(x_n) &gt; \\ln 2\\)</span>.</span></li></ul>\n<p>לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_n &gt; \\ln 2\\)</span>,</span> ובפרט <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> חסומה מלרע על ידי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span>.</span></p>\n<p><strong>שלב 2: מונוטוניות והוכחת ההתכנסות</strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> כבר ראינו <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_n &gt; \\ln 2\\)</span>,</span></span> ולכן לפי סעיף (1) מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[x_{n+1} = g(x_n) &lt; x_n.\\]</div>\n<p>הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> היא אפוא מונוטונית יורדת (למעשה יורדת ממש, הגדרה 3.15) וחסומה מלרע. לפי משפט ההתכנסות המונוטונית (משפט 3.16), הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> מתכנסת לגבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L = \\lim_{n\\to\\infty} x_n\\)</span>.</span> (מעמידות ושמירת סדר משפט 2.31 נובע גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\ge\\ln 2\\)</span>,</span> אך מיד נמצא את <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> במדויק.)</p>\n<p><strong>שלב 3: חישוב הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span></strong> מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((x_{n+1})\\)</span></span> היא זנב של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span>,</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} x_{n+1} = L\\)</span> (משפט 2.17). כמו כן, הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(e^t\\)</span> רציפה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (משפט 6.9), ולכן לפי אפיון היינה לרציפות (טענה 5.4) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} e^{x_n} = e^L &gt; 0\\)</span>.</span> כעת נעבור לגבול בשני אגפי נוסחת הרקורסיה <span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+1} = x_n + \\frac{2}{e^{x_n}} - 1\\)</span> בעזרת אריתמטיקה של גבולות (משפט 2.28, שכן המכנה שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^L\\ne 0\\)</span>):</span></span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L = L + \\frac{2}{e^L} - 1.\\]</div>\n<p>נחסר <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> משני האגפים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{2}{e^L} = 1 \\implies e^L = 2 \\implies L = \\ln 2.\\]</div>\n<p>מכאן כי <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> מתכנסת וגבולה הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} x_n = \\ln 2\\)</span>.</span> <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>שלב 1: חסימות מלרע <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x_n &gt; \\ln 2\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>)</span></strong> נבדוק באינדוקציה על <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_n &gt; \\ln 2\\)</span>:</span></p>\n<ul><li><strong>בסיס <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(n=1\\)</span>)</span></strong>: כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e &gt; 2\\)</span></span> (כי <span class=\"math math-inline\" dir=\"ltr\">\\(e=\\lim_{n\\to\\infty}(1+\\frac{1}{n})^n\\)</span> וכל איבר <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span></span> גדול <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>)</span></span> והפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln\\)</span> עולה ממש (משפט 6.14), מתקיים</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[x_1 = 1 = \\ln e &gt; \\ln 2.\\]</div>\n<ul><li><strong>צעד</strong>: נניח כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_n &gt; \\ln 2\\)</span>.</span> אז לפי סעיף (2), מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+1} = g(x_n) &gt; \\ln 2\\)</span>.</span></li></ul>\n<p>לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_n &gt; \\ln 2\\)</span>,</span> ובפרט <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> חסומה מלרע על ידי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 2\\)</span>.</span></p>","<p><strong>שלב 2: מונוטוניות והוכחת ההתכנסות</strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> כבר ראינו <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_n &gt; \\ln 2\\)</span>,</span></span> ולכן לפי סעיף (1) מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[x_{n+1} = g(x_n) &lt; x_n.\\]</div>\n<p>הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> היא אפוא מונוטונית יורדת (למעשה יורדת ממש, הגדרה 3.15) וחסומה מלרע. לפי משפט ההתכנסות המונוטונית (משפט 3.16), הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> מתכנסת לגבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L = \\lim_{n\\to\\infty} x_n\\)</span>.</span> (מעמידות ושמירת סדר משפט 2.31 נובע גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\ge\\ln 2\\)</span>,</span> אך מיד נמצא את <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> במדויק.)</p>","<p><strong>שלב 3: חישוב הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span></strong> מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((x_{n+1})\\)</span></span> היא זנב של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span>,</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} x_{n+1} = L\\)</span> (משפט 2.17). כמו כן, הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(e^t\\)</span> רציפה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (משפט 6.9), ולכן לפי אפיון היינה לרציפות (טענה 5.4) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} e^{x_n} = e^L &gt; 0\\)</span>.</span> כעת נעבור לגבול בשני אגפי נוסחת הרקורסיה <span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+1} = x_n + \\frac{2}{e^{x_n}} - 1\\)</span> בעזרת אריתמטיקה של גבולות (משפט 2.28, שכן המכנה שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^L\\ne 0\\)</span>):</span></span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L = L + \\frac{2}{e^L} - 1.\\]</div>\n<p>נחסר <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> משני האגפים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{2}{e^L} = 1 \\implies e^L = 2 \\implies L = \\ln 2.\\]</div>\n<p>מכאן כי <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> מתכנסת וגבולה הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} x_n = \\ln 2\\)</span>.</span> <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות שכדאי להימנע מהן</p><div class=\"callout-body\"><ul><li>להציב גבול <span class=\"math math-inline\" dir=\"ltr\">\\(L = g(L)\\)</span> <strong>לפני</strong> שמוכיחים שהגבול בכלל קיים — משפט 3.16 (שדורש גם מונוטוניות וגם חסימות) הוא תנאי חיוני לפני פתרון משוואת נקודת השבת!</li><li>להניח <span class=\"math math-inline\" dir=\"ltr\">\\(x_n &gt; \\ln 2\\)</span> רק עבור <span class=\"math math-inline\" dir=\"ltr\">\\(n=1\\)</span> בלי לציין שהדבר עובר באינדוקציה לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> בעזרת סעיף (2).</li></ul></div></div>"}],"similar":"","mc":null},"4":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p><strong>א.</strong> (10 נק׳) הוכיחו שהפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sqrt{x}\\sin\\sqrt{x}\\)</span> רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>.</span></span></p>\n<p><strong>ב.</strong> (15 נק׳) תהי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> פונקציה רציפה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span> וגזירה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span> נניח כי <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span> וכי <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> מונוטונית עולה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span> (1) הוכיחו שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x} &lt; f'(x)\\)</span>.</span> (2) הוכיחו שהפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{f(x)}{x}\\)</span> מונוטונית עולה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">על החלק ההתחלתי <span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span> משפט קנטור נותן רציפות במ״ש אוטומטית, ועל הזנב <span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span> הנגזרת נשארת חסומה מתחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> — וכשתופרים את שני הקטעים החופפים יחד, מקבלים רציפות במ״ש על כל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>.</span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: על החלק ההתחלתי <span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span> משפט קנטור נותן רציפות במ״ש אוטומטית, ועל הזנב <span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span> הנגזרת נשארת חסומה מתחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> — וכשתופרים את שני הקטעים החופפים יחד, מקבלים רציפות במ״ש על כל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>.</span></p>\n<p><strong>תמונה בראש</strong>: למרות שליד <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> השורש <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}\\)</span> מטפס תלול מאוד ולכן הנגזרת של <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}\\)</span> מתפוצצת באפס, שום אסון לא קורה כי הקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span> סגור וחסום ושם משפט קנטור מסדר הכול. הרחק מאפס, <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>,</span></span> כשאנחנו גוזרים את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}\\sin\\sqrt{x}\\)</span>,</span> <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}\\)</span></span> בצד אחד מתקזז עם <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{2\\sqrt{x}}\\)</span> ובצד השני <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sin\\sqrt{x}}{2\\sqrt{x}}\\)</span> קטן עוד יותר — אז השיפוע נשאר קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> לנצח!</p>\n<p><strong>עם מספרים</strong>: בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f'(x)| = \\left|\\frac{\\sin\\sqrt{x}}{2\\sqrt{x}} + \\frac{\\cos\\sqrt{x}}{2}\\right| \\le \\frac{1}{2} + \\frac{1}{2} = 1\\)</span>.</span> למשל <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=100\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f'(100)| = \\left|\\frac{\\sin 10}{20} + \\frac{\\cos 10}{2}\\right| \\le 0.05 + 0.5 = 0.55 \\le 1\\)</span>.</span> לכן בשום מקום מעל <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> הגרף לא קופץ מהר יותר <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\cdot|x-y|\\)</span>.</span></span></p>\n<p><strong>מושגים</strong>:</p>\n<ul><li><strong>רציפות במידה שווה (הגדרה 5.46)</strong>: אפשר למצוא <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> אחיד לכל הקטע כך שכל זוג נקודות הקרובות זו לזו בפחות <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span></span> נותן ערכי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> קרובים בפחות <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>.</span></span></li><li><strong>נגזרת חסומה גוררת רציפות במ״ש (מסקנה מלגראנז׳, משפט 8.6)</strong>: אם <span class=\"math math-inline\" dir=\"ltr\">\\(|f'(c)|\\le M\\)</span> בכל קטע גזירות, אז <span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|\\le M|x-y|\\)</span> לכל זוג בקטע.</li></ul></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;latex&quot;:&quot;f(x)=\\\\sqrt{x}\\\\sin(\\\\sqrt{x})+0\\\\cdot\\\\sqrt{x}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;latex&quot;:&quot;y=\\\\sqrt{x}+0\\\\cdot\\\\sqrt{x}&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;latex&quot;:&quot;y=-\\\\sqrt{x}+0\\\\cdot\\\\sqrt{x}&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;latex&quot;:&quot;x=1&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;latex&quot;:&quot;x=2&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: אל תנסו לחסום את $f'(x)$ ליד $x=0$! פצלו לקטע קומפקטי ולקרן","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: אל תנסו לחסום את <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span> ליד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>!</span> פצלו לקטע קומפקטי ולקרן</p><div class=\"callout-body\"><p>השאירו את <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> בתוך קטע סגור וחסום <span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span> שבו <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה, ולכן רציפה במ״ש ממשפט קנטור (משפט 5.48). על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>,</span> גזרו וחסמו את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span>.</span></p></div></div>"},{"title":"רמז 2: למה כדאי לבחור חפיפה $[0,2]$ ו-$[1,\\infty)$ במקום $[0,1]$ ו-$[1,\\infty)$?","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: למה כדאי לבחור חפיפה <span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></span> במקום <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>?</span></span></p><div class=\"callout-body\"><p>כששני הקטעים חופפים על <span class=\"math math-inline\" dir=\"ltr\">\\([1,2]\\)</span> באורך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span> כל זוג נקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,\\infty)\\)</span> שמרחקן קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> נופל בהכרח יחד או לתוך <span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span> או לתוך <span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span> — וכך איחוד הרציפויות המ״ש מיידי!</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">תוכנית ההוכחה</p><div class=\"callout-body\"><ol><li>נראה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>,</span></span> ובפרט רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span>,</span></span> ולכן רציפה במ״ש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span></span> לפי משפט קנטור (משפט 5.48).</li><li>נגזור את <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span></span> נחסום <span class=\"math math-inline\" dir=\"ltr\">\\(|f'(x)|\\le 1\\)</span> בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>,</span> ונשתמש במשפט לגראנז׳ (משפט 8.6) כדי להראות <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה במ״ש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_2=\\varepsilon\\)</span>.</span></li><li>נתפור את שני הקטעים החופפים: בהינתן <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span> ניקח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\min\\{\\delta_1,\\varepsilon,1\\}\\)</span>,</span> ונראה שכל זוג <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,\\infty)\\)</span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta\\)</span> נמצא כולו <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span></span> או כולו <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>.</span></span></li></ol></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון</p><div class=\"callout-body\"><p><strong>שלב 1: רציפות במ״ש בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span></strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> (כהפוכה של <span class=\"math math-inline\" dir=\"ltr\">\\(t^2\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>,</span></span> משפט 5.43), והפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin t\\)</span> רציפה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (טענה 5.7). לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sqrt{x}\\sin\\sqrt{x}\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> כמכפלה והרכבה של פונקציות רציפות (משפטים 5.11, 5.15). בפרט, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בקטע הסגור והחסום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span>,</span> ולכן לפי משפט קנטור (משפט 5.48), <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במ״ש בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span>.</span></p>\n<p><strong>שלב 2: חסימת הנגזרת ורציפות במ״ש בקרן <span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}=x^{1/2}\\)</span> גזירה עם נגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{2\\sqrt{x}}\\)</span> (משפט 7.27/7.31), <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin t\\)</span></span> גזירה עם נגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(\\cos t\\)</span> (טענה 7.22). לפי כלל המכפלה (משפט 7.14) וכלל השרשרת (משפט 7.21), <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span></span> ונגזרתה היא</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x) = \\frac{1}{2\\sqrt{x}}\\sin\\sqrt{x} + \\sqrt{x}\\cos\\sqrt{x}\\cdot\\frac{1}{2\\sqrt{x}} = \\frac{\\sin\\sqrt{x}}{2\\sqrt{x}} + \\frac{1}{2}\\cos\\sqrt{x}.\\]</div>\n<p>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}\\ge 1\\)</span>,</span> וכן <span class=\"math math-inline\" dir=\"ltr\">\\(|\\sin\\sqrt{x}|\\le 1\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\cos\\sqrt{x}|\\le 1\\)</span>.</span></span> לכן מאי-שוויון המשולש (טענה 1.49):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f'(x)| \\le \\frac{|\\sin\\sqrt{x}|}{2\\sqrt{x}} + \\frac{|\\cos\\sqrt{x}|}{2} \\le \\frac{1}{2\\cdot 1} + \\frac{1}{2} = 1 \\qquad \\text{לכל } x\\ge 1.\\]</div>\n<p>כעת, לכל שתי נקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[1,\\infty)\\)</span> (נניח בה״כ <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;y\\)</span>),</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([x,y]\\)</span></span> וגזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((x,y)\\)</span>,</span></span> ולכן לפי משפט לגראנז׳ (משפט 8.6) קיים <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(x,y)\\subset(1,\\infty)\\)</span> כך ש-</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f(x)-f(y)| = |f'(c)|\\,|x-y| \\le 1\\cdot|x-y| = |x-y|.\\]</div>\n<p>(עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x=y\\)</span> האי-שוויון <span class=\"math math-inline\" dir=\"ltr\">\\(0\\le 0\\)</span> מתקיים מאליו.)</p>\n<p><strong>שלב 3: איחוד הקטעים לפי הגדרה 5.46</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span> מרציפות במ״ש של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span> (שלב 1), קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_1&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,2]\\)</span> המקיימים <span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta_1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\varepsilon\\)</span>.</span> נגדיר</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\delta = \\min\\{\\delta_1,\\, \\varepsilon,\\, 1\\} &gt; 0.\\]</div>\n<p>יהיו <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,\\infty)\\)</span> המקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta\\)</span>.</span> נניח בה״כ כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\le y\\)</span>.</span> נחלק לשתי אפשרויות:</p>\n<ul><li><strong>אם <span class=\"math math-inline\" dir=\"ltr\">\\(x &lt; 1\\)</span></strong>: מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y-x = |x-y| &lt; \\delta \\le 1\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y &lt; x+1 &lt; 2\\)</span>,</span> ולכן שתי הנקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\)</span> שייכות לקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span>,</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta\\le\\delta_1\\)</span>.</span> מכאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\varepsilon\\)</span>.</span></li><li><strong>אם <span class=\"math math-inline\" dir=\"ltr\">\\(x \\ge 1\\)</span></strong>: אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y \\ge x \\ge 1\\)</span>,</span> ולכן שתי הנקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\)</span> שייכות לקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>.</span> משלב 2 נובע כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)| \\le |x-y| &lt; \\delta \\le \\varepsilon\\)</span>.</span></li></ul>\n<p>בכל מקרה מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\varepsilon\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במ״ש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> (הגדרה 5.46). <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>שלב 1: רציפות במ״ש בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span></strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> (כהפוכה של <span class=\"math math-inline\" dir=\"ltr\">\\(t^2\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>,</span></span> משפט 5.43), והפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin t\\)</span> רציפה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (טענה 5.7). לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sqrt{x}\\sin\\sqrt{x}\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> כמכפלה והרכבה של פונקציות רציפות (משפטים 5.11, 5.15). בפרט, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בקטע הסגור והחסום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span>,</span> ולכן לפי משפט קנטור (משפט 5.48), <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במ״ש בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span>.</span></p>","<p><strong>שלב 2: חסימת הנגזרת ורציפות במ״ש בקרן <span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}=x^{1/2}\\)</span> גזירה עם נגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{2\\sqrt{x}}\\)</span> (משפט 7.27/7.31), <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin t\\)</span></span> גזירה עם נגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(\\cos t\\)</span> (טענה 7.22). לפי כלל המכפלה (משפט 7.14) וכלל השרשרת (משפט 7.21), <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span></span> ונגזרתה היא</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x) = \\frac{1}{2\\sqrt{x}}\\sin\\sqrt{x} + \\sqrt{x}\\cos\\sqrt{x}\\cdot\\frac{1}{2\\sqrt{x}} = \\frac{\\sin\\sqrt{x}}{2\\sqrt{x}} + \\frac{1}{2}\\cos\\sqrt{x}.\\]</div>\n<p>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}\\ge 1\\)</span>,</span> וכן <span class=\"math math-inline\" dir=\"ltr\">\\(|\\sin\\sqrt{x}|\\le 1\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\cos\\sqrt{x}|\\le 1\\)</span>.</span></span> לכן מאי-שוויון המשולש (טענה 1.49):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f'(x)| \\le \\frac{|\\sin\\sqrt{x}|}{2\\sqrt{x}} + \\frac{|\\cos\\sqrt{x}|}{2} \\le \\frac{1}{2\\cdot 1} + \\frac{1}{2} = 1 \\qquad \\text{לכל } x\\ge 1.\\]</div>\n<p>כעת, לכל שתי נקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[1,\\infty)\\)</span> (נניח בה״כ <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;y\\)</span>),</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([x,y]\\)</span></span> וגזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((x,y)\\)</span>,</span></span> ולכן לפי משפט לגראנז׳ (משפט 8.6) קיים <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(x,y)\\subset(1,\\infty)\\)</span> כך ש-</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f(x)-f(y)| = |f'(c)|\\,|x-y| \\le 1\\cdot|x-y| = |x-y|.\\]</div>\n<p>(עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x=y\\)</span> האי-שוויון <span class=\"math math-inline\" dir=\"ltr\">\\(0\\le 0\\)</span> מתקיים מאליו.)</p>","<p><strong>שלב 3: איחוד הקטעים לפי הגדרה 5.46</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span> מרציפות במ״ש של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span> (שלב 1), קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_1&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,2]\\)</span> המקיימים <span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta_1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\varepsilon\\)</span>.</span> נגדיר</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\delta = \\min\\{\\delta_1,\\, \\varepsilon,\\, 1\\} &gt; 0.\\]</div>\n<p>יהיו <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,\\infty)\\)</span> המקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta\\)</span>.</span> נניח בה״כ כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\le y\\)</span>.</span> נחלק לשתי אפשרויות:</p>\n<ul><li><strong>אם <span class=\"math math-inline\" dir=\"ltr\">\\(x &lt; 1\\)</span></strong>: מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y-x = |x-y| &lt; \\delta \\le 1\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y &lt; x+1 &lt; 2\\)</span>,</span> ולכן שתי הנקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\)</span> שייכות לקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span>,</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta\\le\\delta_1\\)</span>.</span> מכאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\varepsilon\\)</span>.</span></li><li><strong>אם <span class=\"math math-inline\" dir=\"ltr\">\\(x \\ge 1\\)</span></strong>: אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y \\ge x \\ge 1\\)</span>,</span> ולכן שתי הנקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\)</span> שייכות לקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>.</span> משלב 2 נובע כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)| \\le |x-y| &lt; \\delta \\le \\varepsilon\\)</span>.</span></li></ul>\n<p>בכל מקרה מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\varepsilon\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במ״ש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> (הגדרה 5.46). <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות שכדאי להימנע מהן</p><div class=\"callout-body\"><ul><li>לשכוח שאיחוד של שתי קבוצות שבהן פונקציה רציפה במ״ש אינו אוטומטי אם אין חפיפה (או גשר דרך נקודת התפר עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon/2\\)</span>).</span> הבחירה <span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\le 1\\)</span> פותרת זאת בצורה מושלמת.</li><li>לחשוב <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(|f'(x)|\\le 1\\)</span></span> מתקיים רק החל <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> ולנסות לכתוב <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span></span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>:</span></span> דווקא ליד <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> יש לחשב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sin\\sqrt{x}}{2\\sqrt{x}}\\to \\frac{1}{2}\\)</span>,</span> כך שהפונקציה אמנם בעלת נגזרת חסומה גם ליד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> אבל הפיצול לקטע סגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span> חוסך את הצורך לחשב גבול של <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sin\\sqrt{x}}{\\sqrt{x}}\\)</span> ומונע התעסקות בקצה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>!</span></li></ul></div></div>"},{"label":"ב","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">שיפוע המיתר <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> עד <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> הוא ממוצע ששווה לנגזרת באיזושהי נקודת ביניים <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> לפני <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>;</span> ומאחר שהשיפוע של פונקציה קמורה הולך וגדל, בנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> השיפוע כבר גדול מהממוצע שמאחוריה — ולכן גם היחס <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}\\)</span> (גובה חלקי רוחב) הולך ועולה.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: שיפוע המיתר <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> עד <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> הוא ממוצע ששווה לנגזרת באיזושהי נקודת ביניים <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> לפני <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>;</span> ומאחר שהשיפוע של פונקציה קמורה הולך וגדל, בנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> השיפוע כבר גדול מהממוצע שמאחוריה — ולכן גם היחס <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}\\)</span> (גובה חלקי רוחב) הולך ועולה.</p>\n<p><strong>תמונה בראש</strong>: תחשבו על רץ שמתחיל בעמדת הזינוק <span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span> ומאיץ כל הזמן (כלומר המהירות <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> עולה כל הזמן). המהירות הממוצעת שלו מההתחלה עד זמן <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}\\)</span>:</span> משפט לגראנז׳ אומר שברגע ביניים <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> בין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>,</span></span> המהירות הרגעית שלו הייתה שווה בדיוק לממוצע הזה. בגלל שהוא ממשיך להאיץ <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span></span> עד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>,</span> המהירות שלו בסוף <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span> כבר עוקפת את הממוצע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}\\)</span>!</span> ואם בכל רגע המהירות הנוכחית עוקפת את המהירות הממוצעת עד עכשיו, אז המהירות הממוצעת חייבת לעלות!</p>\n<p><strong>עם מספרים</strong>: ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x^2\\)</span> (כאן <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=2x\\)</span></span> עולה ממש). <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=3\\)</span>:</span></span> שיפוע המיתר מהראשית הוא <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{9}{3}=3\\)</span> (ששווה לנגזרת בנקודת הביניים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c=1.5\\)</span>),</span> והנגזרת בקצה היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(3)=6 &gt; 3\\)</span>.</span> והיחס <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{x^2}{x}=x\\)</span> אכן עולה.</p>\n<p><strong>מושגים</strong>:</p>\n<ul><li><strong>משפט לגראנז׳ (משפט 8.6)</strong>: משווה בין שיפוע מיתר <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)-f(0)}{x-0}\\)</span> לבין הנגזרת בנקודת ביניים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,x)\\)</span>.</span></li><li><strong>הערת מינוח חשוב בקורס (&quot;מונוטונית עולה&quot; לעומת &quot;עולה ממש&quot;)</strong>: בטרמינולוגיה המקובלת בקורס (למשל הגדרה 3.15), &quot;עולה&quot; ללא המילה &quot;ממש&quot; מתירה שוויון <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)\\le f'(x)\\)</span>),</span> ואז עבור <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span> מתקיים שוויון <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}=1=f'(x)\\)</span> ולא אי-שוויון חד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(&lt;\\)</span>.</span> כדי לקבל אי-שוויון חד <span class=\"math math-inline\" dir=\"ltr\">\\(&lt;\\)</span> בסעיף (1) מתכוונים בשאלה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span></span> <strong>עולה ממש</strong>; אם <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> עולה במובן החלש, מקבלים בסעיף (1) <span class=\"math math-inline\" dir=\"ltr\">\\(\\le\\)</span> וסעיף (2) עדיין מתקיים (במובן החלש).</li></ul></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;latex&quot;:&quot;f(x)=e^x-1+0\\\\cdot\\\\sqrt{x}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;latex&quot;:&quot;a=1.2&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.4,&quot;max&quot;:1.8,&quot;step&quot;:0.1}},{&quot;latex&quot;:&quot;y=\\\\frac{e^a-1}{a}x&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;latex&quot;:&quot;y=(e^a-1)+e^a(x-a)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;latex&quot;:&quot;(a, e^a-1)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;(x, f(x))&quot;},{&quot;latex&quot;:&quot;h(x)=\\\\frac{e^x-1}{x}+0\\\\cdot\\\\sqrt{x-0.01}&quot;,&quot;color&quot;:&quot;#fa7e19&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: לסעיף (1) הפעילו את לגראנז׳ על $[0,x]$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: לסעיף (1) הפעילו את לגראנז׳ על <span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span></p><div class=\"callout-body\"><p><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span></span> (כי רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>)</span></span> וגזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,x)\\)</span>,</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span>.</span></span> מה אומר משפט לגראנז׳ על הביטוי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)-f(0)}{x-0}\\)</span>?</span></p></div></div>"},{"title":"רמז 2: לסעיף (2) גזרו את $g(x)=\\frac{f(x)}{x}$ והשתמשו בסעיף (1)!","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: לסעיף (2) גזרו את <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{f(x)}{x}\\)</span> והשתמשו בסעיף (1)!</p><div class=\"callout-body\"><p>חשבו את <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)\\)</span> לפי כלל המנה (משפט 7.18), והראו שמופיע במונה בדיוק הביטוי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(xf'(x)-f(x) = x^2\\cdot\\frac{f'(x)-f(x)/x}{x}\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">תוכנית ההוכחה</p><div class=\"callout-body\"><ol><li><strong>הערת פתיחה</strong>: נציין כי לשם אי-שוויון חד ב-(1) הכוונה היא <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span></span> עולה ממש (ונסביר מה קורה גם במובן החלש).</li><li><strong>סעיף (1)</strong>: לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> נפעיל את משפט לגראנז׳ (משפט 8.6) על <span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span> לקבלת <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,x)\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}=f'(c)\\)</span>.</span> מכך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(c&lt;x\\)</span></span> וממונוטוניות עולה ממש של <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> מתקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}=f'(c)&lt;f'(x)\\)</span>.</span></li><li><strong>סעיף (2)</strong>: נגזור את <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{f(x)}{x}\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span></span> לפי כלל המנה (משפט 7.18) ונקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)=\\frac{xf'(x)-f(x)}{x^2}\\)</span>.</span> מסעיף (1) מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)&gt;0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span>,</span> ולכן לפי משפט 8.17 <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> עולה ממש (ובפרט מונוטונית עולה) <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span></li></ol></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון</p><div class=\"callout-body\"><p><strong>הערה על המינוח &quot;מונוטונית עולה&quot;</strong>: בקורס מקובל ש&quot;עולה&quot; ללא &quot;ממש&quot; מתיר שוויון (הגדרה 3.15). אילו <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> הייתה רק עולה במובן החלש, למשל עבור <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span> המקיימת <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=1\\)</span>,</span></span> מתקיים שוויון <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}=1=f'(x)\\)</span> ולא אי-שוויון חד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(&lt;\\)</span>.</span> לכן בסעיף (1) ברור כי כוונת השאלה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span></span> <strong>עולה ממש</strong> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span></span> (אם <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> עולה במובן החלש, ההוכחה שלהלן נותנת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}\\le f'(x)\\)</span> ב-(1) ועדיין נותנת את (2) במלואו). נכתוב את הפתרון תחת ההנחה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span></span> עולה ממש <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span></p>\n<p><strong>שלב 1: הוכחת תת-סעיף (1)</strong> יהי <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> כלשהו. נבחן את הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span>:</span> מן הנתונים <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> ובפרט רציפה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span>,</span> וגזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span></span> ובפרט גזירה בקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,x)\\)</span>.</span> לפי משפט לגראנז׳ (משפט 8.6), קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,x)\\)</span> שעבורה מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{f(x)-f(0)}{x-0} = f'(c).\\]</div>\n<p>כיוון שנתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span>,</span> נקבל</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{f(x)}{x} = f'(c).\\]</div>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; c &lt; x\\)</span></span> ושתי הנקודות <span class=\"math math-inline\" dir=\"ltr\">\\(c,x\\)</span> נמצאות בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> שבו <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> עולה ממש, מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{f(x)}{x} = f'(c) &lt; f'(x).\\]</div>\n<p><strong>שלב 2: הוכחת תת-סעיף (2)</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{f(x)}{x}\\)</span> היא מנה של שתי פונקציות גזירות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span></span> שהמכנה שלה <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> שונה מאפס בכל הקטע. לכן לפי כלל המנה (משפט 7.18), <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> ונגזרתה היא</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(x) = \\frac{f'(x)\\cdot x - f(x)\\cdot 1}{x^2} = \\frac{f'(x) - \\frac{f(x)}{x}}{x} \\qquad (x&gt;0).\\]</div>\n<p>לפי תת-סעיף (1), לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x} &lt; f'(x)\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x) - \\frac{f(x)}{x} &gt; 0\\)</span>.</span> מאחר שגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(x) &gt; 0 \\qquad \\text{לכל } x\\in(0,\\infty).\\]</div>\n<p>לפי משפט 8.17, הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> עולה ממש (ובפרט מונוטונית עולה) בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span> <em>(הערה: גם אם <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> עולה במובן החלש בלבד, מקבלים <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)-\\frac{f(x)}{x}\\ge 0\\)</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)\\ge 0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>;</span> אז לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;x_1&lt;x_2\\)</span>,</span> ממשפט לגראנז׳ על <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([x_1,x_2]\\)</span> מתקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x_2)-g(x_1)=g'(c)(x_2-x_1)\\ge 0\\)</span>,</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span></span> עדיין מונוטונית עולה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.)</span></span></em> <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>הערה על המינוח &quot;מונוטונית עולה&quot;</strong>: בקורס מקובל ש&quot;עולה&quot; ללא &quot;ממש&quot; מתיר שוויון (הגדרה 3.15). אילו <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> הייתה רק עולה במובן החלש, למשל עבור <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span> המקיימת <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=1\\)</span>,</span></span> מתקיים שוויון <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}=1=f'(x)\\)</span> ולא אי-שוויון חד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(&lt;\\)</span>.</span> לכן בסעיף (1) ברור כי כוונת השאלה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span></span> <strong>עולה ממש</strong> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span></span> (אם <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> עולה במובן החלש, ההוכחה שלהלן נותנת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}\\le f'(x)\\)</span> ב-(1) ועדיין נותנת את (2) במלואו). נכתוב את הפתרון תחת ההנחה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span></span> עולה ממש <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span></p>\n<p><strong>שלב 1: הוכחת תת-סעיף (1)</strong> יהי <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> כלשהו. נבחן את הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span>:</span> מן הנתונים <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> ובפרט רציפה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span>,</span> וגזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span></span> ובפרט גזירה בקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,x)\\)</span>.</span> לפי משפט לגראנז׳ (משפט 8.6), קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,x)\\)</span> שעבורה מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{f(x)-f(0)}{x-0} = f'(c).\\]</div>\n<p>כיוון שנתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span>,</span> נקבל</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{f(x)}{x} = f'(c).\\]</div>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; c &lt; x\\)</span></span> ושתי הנקודות <span class=\"math math-inline\" dir=\"ltr\">\\(c,x\\)</span> נמצאות בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> שבו <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> עולה ממש, מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{f(x)}{x} = f'(c) &lt; f'(x).\\]</div>","<p><strong>שלב 2: הוכחת תת-סעיף (2)</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{f(x)}{x}\\)</span> היא מנה של שתי פונקציות גזירות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span></span> שהמכנה שלה <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> שונה מאפס בכל הקטע. לכן לפי כלל המנה (משפט 7.18), <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> ונגזרתה היא</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(x) = \\frac{f'(x)\\cdot x - f(x)\\cdot 1}{x^2} = \\frac{f'(x) - \\frac{f(x)}{x}}{x} \\qquad (x&gt;0).\\]</div>\n<p>לפי תת-סעיף (1), לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x} &lt; f'(x)\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x) - \\frac{f(x)}{x} &gt; 0\\)</span>.</span> מאחר שגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(x) &gt; 0 \\qquad \\text{לכל } x\\in(0,\\infty).\\]</div>\n<p>לפי משפט 8.17, הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> עולה ממש (ובפרט מונוטונית עולה) בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span> <em>(הערה: גם אם <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> עולה במובן החלש בלבד, מקבלים <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)-\\frac{f(x)}{x}\\ge 0\\)</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)\\ge 0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>;</span> אז לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;x_1&lt;x_2\\)</span>,</span> ממשפט לגראנז׳ על <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([x_1,x_2]\\)</span> מתקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x_2)-g(x_1)=g'(c)(x_2-x_1)\\ge 0\\)</span>,</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span></span> עדיין מונוטונית עולה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.)</span></span></em> <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות שכדאי להימנע מהן</p><div class=\"callout-body\"><ul><li>לשכוח לבדוק <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> כשמפעילים את לגראנז׳ על <span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span> (אילו <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> קפצה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> משפט לגראנז׳ לא היה תקף!).</li><li>לשכוח להתייחס להבדל בין &quot;עולה ממש&quot; ל&quot;עולה חלש&quot;: עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f'=1\\)</span> עולה במובן החלש והאי-שוויון החד <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}&lt;f'(x)\\)</span> אינו מתקיים; חשוב להזכיר נקודה זו בקצרה בפתרון.</li></ul></div></div>"}],"similar":"","mc":null,"options":["א","ב"]},"5":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>תהי</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=\\begin{cases}\\frac{1}{x}e^{-\\frac{1}{x}} &amp; x&gt;0 \\\\ a &amp; x=0 \\\\ x\\ln(-x) &amp; x&lt;0\\end{cases}.\\]</div>\n<p>א. עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span> ב. עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> הינה נקודת אי רציפות מסוג שני של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span>.</span> ג. עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=1\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span> ד. עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=1\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> הינה נקודת אי רציפות מסוג שני של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span>.</span></p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">גם מצד ימין וגם מצד שמאל הפונקציה מתקרבת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> ולכן היא רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בדיוק כאשר הערך בנקודה עצמה הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>.</span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: גם מצד ימין וגם מצד שמאל הפונקציה מתקרבת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> ולכן היא רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בדיוק כאשר הערך בנקודה עצמה הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>.</span></p>\n<p><strong>תמונה בראש</strong>: מימין, כשמתקרבים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> הביטוי <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{x}\\)</span> אמנם גדל לאינסוף, אבל <span class=\"math math-inline\" dir=\"ltr\">\\(e^{-1/x}\\)</span> דוחף לאפס הרבה יותר מהר ממנו — כמו שחקן איטי מול אלוף ספרינט. משמאל, <span class=\"math math-inline\" dir=\"ltr\">\\(-x\\)</span> מתקרב לאפס מהכיוון החיובי ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ln(-x)\\)</span> מתכווץ אף הוא לאפס (איקס חזק מלוג). שני הצדדים נוחתים יחד בגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></p>\n<p><strong>עם מספרים</strong>: מימין <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0.05\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{0.05}e^{-20}=20e^{-20}\\approx 4\\cdot 10^{-8}\\)</span>.</span> משמאל <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=-0.01\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-0.01\\ln(0.01)\\approx 0.046\\)</span>.</span> בשני הצדדים הגבול הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></p>\n<p><strong>מושגים</strong>:</p>\n<ul><li><strong>רציפות בנקודה (משפט 4.48, טענה 5.18)</strong>: פונקציה רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> אם ורק אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}f(x)=\\lim_{x\\to 0^-}f(x)=f(0)\\)</span>.</span></li><li><strong>אי־רציפות סליקה לעומת סוג שני (הגדרות 5.21, 5.23)</strong>: כששני הגבולות החד־צדדיים סופיים ושווים זה לזה אך שונים <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)\\)</span>,</span></span> אי־הרציפות היא סליקה, ולא סוג שני.</li></ul></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;latex&quot;:&quot;a=0&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0,&quot;max&quot;:1,&quot;step&quot;:0.5}},{&quot;latex&quot;:&quot;f(x)=\\\\frac{1}{x}e^{-1/x}+0\\\\cdot\\\\sqrt{x}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;latex&quot;:&quot;g(x)=x\\\\ln(-x)+0\\\\cdot\\\\sqrt{-x}&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;latex&quot;:&quot;(0, a)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;(0, a)&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: הפכו את הגבול מימין לגבול של $t=\\frac{1}{x}\\to\\infty$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: הפכו את הגבול מימין לגבול של <span class=\"math math-inline\" dir=\"ltr\">\\(t=\\frac{1}{x}\\to\\infty\\)</span></p><div class=\"callout-body\"><p><span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span>,</span></span> הביטוי <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{x}e^{-1/x}\\)</span> הופך <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{t}{e^t}\\)</span></span> <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t\\to\\infty\\)</span>.</span></span> מה נותן כלל לופיטל?</p></div></div>"},{"title":"רמז 2: בגבול משמאל הציבו $u=-x\\to 0^+$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: בגבול משמאל הציבו <span class=\"math math-inline\" dir=\"ltr\">\\(u=-x\\to 0^+\\)</span></p><div class=\"callout-body\"><p>מקבלים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-u\\ln u = -\\frac{\\ln u}{1/u}\\)</span>.</span> חשבו עם לופיטל <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{-\\infty}{\\infty}\\)</span>),</span> וזכרו שאם שני הגבולות שווים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> אז עבור <span class=\"math math-inline\" dir=\"ltr\">\\(a=1\\)</span> מתקבלת אי-רציפות סליקה (לא מסוג שני!).</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">תוכנית הפתרון</p><div class=\"callout-body\"><ol><li>נחשב את <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+} f(x)\\)</span> בהצבת <span class=\"math math-inline\" dir=\"ltr\">\\(t=\\frac{1}{x}\\to\\infty\\)</span> ולופיטל על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{t}{e^t}\\to 0\\)</span>.</span></li><li>נחשב את <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-} f(x)\\)</span> בהצבת <span class=\"math math-inline\" dir=\"ltr\">\\(u=-x\\to 0^+\\)</span> ולופיטל על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\ln u}{1/u}\\to 0\\)</span>.</span></li><li>נסיק <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0} f(x)=0\\)</span>,</span></span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> (א נכונה), ואינה מסוג שני לא <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span></span> ולא <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=1\\)</span>.</span></span></li></ol></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון</p><div class=\"callout-body\"><p><strong>התשובה: א.</strong></p>\n<p><strong>שלב 1: חישוב הגבול מימין <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+} f(x)\\)</span></strong> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{1/x}{e^{1/x}}\\)</span>.</span> <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span>,</span></span> המשתנה <span class=\"math math-inline\" dir=\"ltr\">\\(t=\\frac{1}{x}\\)</span> שואף <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span></span> (משפט 4.53). נחשב <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{t\\to\\infty}\\frac{t}{e^t}\\)</span> לפי כלל לופיטל לצורת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\infty}{\\infty}\\)</span> באינסוף (משפט 8.16): <span class=\"math math-inline\" dir=\"ltr\">\\(t\\to\\infty\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^t\\to\\infty\\)</span>,</span></span> שתיהן גזירות עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((e^t)'=e^t\\ne 0\\)</span>,</span> ומתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{t\\to\\infty}\\frac{(t)'}{(e^t)'} = \\lim_{t\\to\\infty}\\frac{1}{e^t} = 0.\\]</div>\n<p>לכן (מהרכבת גבולות, משפט 4.39 המורחב לאינסוף) מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+} f(x) = \\lim_{x\\to 0^+}\\frac{1}{x}e^{-\\frac{1}{x}} = 0.\\]</div>\n<p><strong>שלב 2: חישוב הגבול משמאל <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-} f(x)\\)</span></strong> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-x&gt;0\\)</span>,</span> ולכן נגדיר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u=-x&gt;0\\)</span>.</span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^-\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u\\to 0^+\\)</span>.</span> נחשב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{u\\to 0^+}(-u\\ln u) = -\\lim_{u\\to 0^+}\\frac{\\ln u}{1/u}\\)</span>:</span> זוהי צורת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{-\\infty}{\\infty}\\)</span> (משפט 6.14 ומשפט 4.53), ולפי כלל לופיטל החד-צדדי (משפט 8.14, 8.16):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{u\\to 0^+}\\frac{\\ln u}{1/u} = \\lim_{u\\to 0^+}\\frac{1/u}{-1/u^2} = \\lim_{u\\to 0^+}(-u) = 0.\\]</div>\n<p>לכן</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^-} f(x) = \\lim_{x\\to 0^-} x\\ln(-x) = 0.\\]</div>\n<p><strong>שלב 3: בחירת הטענה הנכונה</strong> מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+} f(x) = \\lim_{x\\to 0^-} f(x) = 0\\)</span>,</span></span> הגבול הדו-צדדי קיים ושווה <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0} f(x)=0\\)</span> (משפט 4.48).</p>\n<ul><li>עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>:</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0=\\lim_{x\\to 0} f(x)\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span> מכאן טענה <strong>א</strong> נכונה (וב שגויה).</li><li>עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=1\\)</span>:</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0} f(x)=0\\ne 1=f(0)\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> היא נקודת אי-רציפות <strong>סליקה</strong> (הגדרה 5.21), ולא אי-רציפות מסוג שני (ג ו-ד שגויות). <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></li></ul></div></div>","steps":["<p><strong>התשובה: א.</strong></p>\n<p><strong>שלב 1: חישוב הגבול מימין <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+} f(x)\\)</span></strong> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{1/x}{e^{1/x}}\\)</span>.</span> <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span>,</span></span> המשתנה <span class=\"math math-inline\" dir=\"ltr\">\\(t=\\frac{1}{x}\\)</span> שואף <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span></span> (משפט 4.53). נחשב <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{t\\to\\infty}\\frac{t}{e^t}\\)</span> לפי כלל לופיטל לצורת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\infty}{\\infty}\\)</span> באינסוף (משפט 8.16): <span class=\"math math-inline\" dir=\"ltr\">\\(t\\to\\infty\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^t\\to\\infty\\)</span>,</span></span> שתיהן גזירות עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((e^t)'=e^t\\ne 0\\)</span>,</span> ומתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{t\\to\\infty}\\frac{(t)'}{(e^t)'} = \\lim_{t\\to\\infty}\\frac{1}{e^t} = 0.\\]</div>\n<p>לכן (מהרכבת גבולות, משפט 4.39 המורחב לאינסוף) מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+} f(x) = \\lim_{x\\to 0^+}\\frac{1}{x}e^{-\\frac{1}{x}} = 0.\\]</div>","<p><strong>שלב 2: חישוב הגבול משמאל <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-} f(x)\\)</span></strong> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-x&gt;0\\)</span>,</span> ולכן נגדיר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u=-x&gt;0\\)</span>.</span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^-\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u\\to 0^+\\)</span>.</span> נחשב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{u\\to 0^+}(-u\\ln u) = -\\lim_{u\\to 0^+}\\frac{\\ln u}{1/u}\\)</span>:</span> זוהי צורת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{-\\infty}{\\infty}\\)</span> (משפט 6.14 ומשפט 4.53), ולפי כלל לופיטל החד-צדדי (משפט 8.14, 8.16):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{u\\to 0^+}\\frac{\\ln u}{1/u} = \\lim_{u\\to 0^+}\\frac{1/u}{-1/u^2} = \\lim_{u\\to 0^+}(-u) = 0.\\]</div>\n<p>לכן</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^-} f(x) = \\lim_{x\\to 0^-} x\\ln(-x) = 0.\\]</div>","<p><strong>שלב 3: בחירת הטענה הנכונה</strong> מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+} f(x) = \\lim_{x\\to 0^-} f(x) = 0\\)</span>,</span></span> הגבול הדו-צדדי קיים ושווה <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0} f(x)=0\\)</span> (משפט 4.48).</p>\n<ul><li>עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>:</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0=\\lim_{x\\to 0} f(x)\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span> מכאן טענה <strong>א</strong> נכונה (וב שגויה).</li><li>עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=1\\)</span>:</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0} f(x)=0\\ne 1=f(0)\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> היא נקודת אי-רציפות <strong>סליקה</strong> (הגדרה 5.21), ולא אי-רציפות מסוג שני (ג ו-ד שגויות). <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></li></ul>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות שכדאי להימנע מהן</p><div class=\"callout-body\"><ul><li>לטעון שעבור <span class=\"math math-inline\" dir=\"ltr\">\\(a=1\\)</span> הנקודה היא מסוג שני כי לא מקבלים רציפות — אי-רציפות מסוג שני מתרחשת רק כשאחד הגבולות החד-צדדיים אינו קיים (במובן הסופי); כאן שניהם קיימים ושווים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></li><li>לטעות בסימן של <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln(-x)\\)</span> <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>:</span></span> כאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-x&gt;0\\)</span>,</span> כך שהלוגריתם מוגדר היטב לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>.</span></li></ul></div></div>"}],"similar":"","mc":{"answer":"א"}},"6":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>תהי</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=\\begin{cases}\\frac{|\\sin x|}{x} &amp; x\\ne 0 \\\\ 1 &amp; x=0\\end{cases}.\\]</div>\n<p>אז א. <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> היא נקודת אי רציפות מסוג שני. ב. קיימת פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> המוגדרת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=g(x)\\)</span> (כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> ומתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'=g\\)</span>).</span> ג. קיימת פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> המוגדרת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(h'(x)=f(x)\\)</span> (כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> ומתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'=f\\)</span>).</span> ד. אף אחת מהטענות הנ״ל אינה נכונה.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">ליד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> מימין מקבלים <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> ומשמאל מקבלים <span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span> (כי <span class=\"math math-inline\" dir=\"ltr\">\\(|\\sin x|\\)</span> חיובי גם <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> שלילי) — כלומר יש קפיצה (סוג ראשון), ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גם אינה גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> וגם אינה יכולה להיות נגזרת של אף פונקציה!</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: ליד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> מימין מקבלים <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> ומשמאל מקבלים <span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span> (כי <span class=\"math math-inline\" dir=\"ltr\">\\(|\\sin x|\\)</span> חיובי גם <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> שלילי) — כלומר יש קפיצה (סוג ראשון), ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גם אינה גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> וגם אינה יכולה להיות נגזרת של אף פונקציה!</p>\n<p><strong>תמונה בראש</strong>: דמיינו כביש שעולה בקו ישר בגובה <span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span> משמאל <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> ואז ברגע שעוברים את <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> קופץ בגובה ישר <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(+1\\)</span>.</span></span> בגלל שהכביש מגיע בשלום לשתי מדרגות שונות <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(+1\\)</span>),</span></span> זו קפיצה רגילה (&quot;סוג ראשון&quot;), לא סוג שני. ובגלל שיש לו קפיצה, אי אפשר לגזור אותו <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> ואפילו יותר מעניין: לפי משפט דארבו לנגזרת, <em>נגזרת של פונקציה לעולם לא יכולה לעשות קפיצת מדרגה</em> — לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גם לא יכולה להיות נגזרת של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span>!</span></p>\n<p><strong>עם מספרים</strong>: <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0.01\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{|\\sin(0.01)|}{0.01}\\approx +0.99998\\)</span>.</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=-0.01\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\sin(-0.01)| = +\\sin(0.01)\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{|\\sin(-0.01)|}{-0.01}\\approx -0.99998\\)</span>.</span> הקפיצה <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span></span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(+1\\)</span></span> בולטת לעין.</p>\n<p><strong>מושגים</strong>:</p>\n<ul><li><strong>אי־רציפות ממין ראשון — &quot;קפיצה&quot; (הגדרה 5.22)</strong>: שני הגבולות החד־צדדיים קיימים וסופיים אך שונים זה מזה.</li><li><strong>משפט דארבו ומסקנותיו (משפטים 8.10–8.12)</strong>: לפונקציה שהיא נגזרת של פונקציה גזירה על קטע אין נקודות אי־רציפות ממין ראשון (לא סליקות ולא קפיצות).</li></ul></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;latex&quot;:&quot;f(x)=\\\\frac{|\\\\sin(x)|}{x}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;latex&quot;:&quot;(0, 1)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;lim 0^+ = f(0) = 1&quot;},{&quot;latex&quot;:&quot;(0, -1)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;pointStyle&quot;:&quot;OPEN&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;lim 0^- = -1&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: חשבו את $\\lim_{x\\to 0^+} f(x)$ ואת $\\lim_{x\\to 0^-} f(x)$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: חשבו את <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+} f(x)\\)</span> ואת <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-} f(x)\\)</span></p><div class=\"callout-body\"><p><span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\pi)\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin x &gt; 0\\)</span>,</span> <span class=\"nobr\">וב-<span class=\"math math-inline\" dir=\"ltr\">\\((-\\pi, 0)\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin x &lt; 0\\)</span>.</span> מכאן נוצרת הפיכת סימן <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(|\\sin x|\\)</span></span> והשתמשו במשפט 4.45 <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sin x}{x}\\to 1\\)</span>).</span></p></div></div>"},{"title":"רמז 2: למה גם ב וגם ג נפסלות מיד מהקפיצה ב-$0$?","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: למה גם ב וגם ג נפסלות מיד מהקפיצה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>?</span></span></p><div class=\"callout-body\"><p>עבור ב: אם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> היא אינה גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> (משפט 7.9). עבור ג: היעזרו במשפט 8.11 או משפט 8.12 — נגזרת בקטע אינה יכולה להיות בעלת אי-רציפות ממין ראשון!</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">תוכנית הפתרון</p><div class=\"callout-body\"><ol><li>נחשב את הגבולות החד-צדדיים של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>:</span></span> <span class=\"math math-inline\" dir=\"ltr\">\\(+1\\)</span> מימין <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span></span> משמאל (בעזרת משפט 4.45), ונסיק שאי-הרציפות היא ממין ראשון (א שגויה).</li><li>מאי-רציפות <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> נסיק לפי משפט 7.9 <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> אינה גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> (ב שגויה).</li><li>לפי משפט 8.11 (ומשפט 8.12), אילו <span class=\"math math-inline\" dir=\"ltr\">\\(h'=f\\)</span> הייתה נגזרת על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span> מעצם קיום הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-} h'(x)=-1\\)</span> היה נובע <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'(0)=-1\\)</span>,</span></span> בסתירה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=1\\)</span></span> (ג שגויה).</li><li>נבחר באפשרות ד.</li></ol></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון</p><div class=\"callout-body\"><p><strong>התשובה: ד.</strong></p>\n<p><strong>שלב 1: חישוב הגבולות החד-צדדיים של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> וסיווג אי-הרציפות</strong></p>\n<ul><li>עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\pi)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin x &gt; 0\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\sin x| = \\sin x\\)</span>.</span> לפיכך, לפי משפט 4.45:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+} f(x) = \\lim_{x\\to 0^+}\\frac{\\sin x}{x} = 1.\\]</div>\n<ul><li>עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(-\\pi, 0)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin x &lt; 0\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\sin x| = -\\sin x\\)</span>.</span> לפיכך</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^-} f(x) = \\lim_{x\\to 0^-}\\left(-\\frac{\\sin x}{x}\\right) = -1.\\]</div>\n<p>שני הגבולות החד-צדדיים קיימים וסופיים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span>)</span></span> ושונים זה מזה. לפיכך <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> היא נקודת אי-רציפות <strong>ממין ראשון</strong> (&quot;קפיצה&quot;, הגדרה 5.22), ולא ממין שני. טענה <strong>א</strong> שגויה.</p>\n<p><strong>שלב 2: שלילת טענה ב (גזירות של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span>)</span></strong> מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-} f(x)=-1 \\ne 1 = f(0)\\)</span>,</span></span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span> לפי משפט 7.9 (פונקציה גזירה בנקודה רציפה בה), <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה גזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>,</span></span> ובפרט אינה גזירה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span> טענה <strong>ב</strong> שגויה.</p>\n<p><strong>שלב 3: שלילת טענה ג <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> כפונקציה קדומה / נגזרת של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span>)</span></strong> נניח בשלילה כי קיימת פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> הגזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h'(x)=f(x)\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>.</span> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span></span> גזירה בסביבת <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> ולנגזרתה <span class=\"math math-inline\" dir=\"ltr\">\\(h'=f\\)</span> קיים גבול סופי משמאל <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-} h'(x)=-1\\)</span>,</span> משפט 8.11 קובע כי <span class=\"math math-inline\" dir=\"ltr\">\\(h'\\)</span> רציפה משמאל <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> כלומר בהכרח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'(0) = \\lim_{x\\to 0^-} h'(x) = -1\\)</span>.</span> אולם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'(0) = f(0) = 1 \\ne -1\\)</span>,</span> סתירה! (באופן שקול, לפי משפט 8.12 לנגזרת של פונקציה גזירה בקטע לא ייתכנו נקודות אי-רציפות ממין ראשון — כמו הקפיצה של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.)</span></span> לכן טענה <strong>ג</strong> שגויה.</p>\n<p>מאחר שטענות א, ב, ג כולן שגויות, הטענה הנכונה היא <strong>ד</strong>. <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>התשובה: ד.</strong></p>\n<p><strong>שלב 1: חישוב הגבולות החד-צדדיים של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> וסיווג אי-הרציפות</strong></p>\n<ul><li>עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\pi)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin x &gt; 0\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\sin x| = \\sin x\\)</span>.</span> לפיכך, לפי משפט 4.45:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+} f(x) = \\lim_{x\\to 0^+}\\frac{\\sin x}{x} = 1.\\]</div>\n<ul><li>עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(-\\pi, 0)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin x &lt; 0\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\sin x| = -\\sin x\\)</span>.</span> לפיכך</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^-} f(x) = \\lim_{x\\to 0^-}\\left(-\\frac{\\sin x}{x}\\right) = -1.\\]</div>\n<p>שני הגבולות החד-צדדיים קיימים וסופיים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span>)</span></span> ושונים זה מזה. לפיכך <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> היא נקודת אי-רציפות <strong>ממין ראשון</strong> (&quot;קפיצה&quot;, הגדרה 5.22), ולא ממין שני. טענה <strong>א</strong> שגויה.</p>","<p><strong>שלב 2: שלילת טענה ב (גזירות של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span>)</span></strong> מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-} f(x)=-1 \\ne 1 = f(0)\\)</span>,</span></span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span> לפי משפט 7.9 (פונקציה גזירה בנקודה רציפה בה), <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה גזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>,</span></span> ובפרט אינה גזירה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span> טענה <strong>ב</strong> שגויה.</p>","<p><strong>שלב 3: שלילת טענה ג <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> כפונקציה קדומה / נגזרת של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span>)</span></strong> נניח בשלילה כי קיימת פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> הגזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h'(x)=f(x)\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>.</span> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span></span> גזירה בסביבת <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> ולנגזרתה <span class=\"math math-inline\" dir=\"ltr\">\\(h'=f\\)</span> קיים גבול סופי משמאל <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-} h'(x)=-1\\)</span>,</span> משפט 8.11 קובע כי <span class=\"math math-inline\" dir=\"ltr\">\\(h'\\)</span> רציפה משמאל <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> כלומר בהכרח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'(0) = \\lim_{x\\to 0^-} h'(x) = -1\\)</span>.</span> אולם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'(0) = f(0) = 1 \\ne -1\\)</span>,</span> סתירה! (באופן שקול, לפי משפט 8.12 לנגזרת של פונקציה גזירה בקטע לא ייתכנו נקודות אי-רציפות ממין ראשון — כמו הקפיצה של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.)</span></span> לכן טענה <strong>ג</strong> שגויה.</p>\n<p>מאחר שטענות א, ב, ג כולן שגויות, הטענה הנכונה היא <strong>ד</strong>. <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות שכדאי להימנע מהן</p><div class=\"callout-body\"><ul><li>לטעות ולחשוב <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}\\frac{|\\sin x|}{x} = 1\\)</span></span> כי מוחקים בטעות את הערך המוחלט גם <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>!</span></span></li><li>לבלבל בין שאלה &quot;האם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה גזירה&quot; לבין &quot;האם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה יכולה להיות <em>נגזרת</em> של <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span>&quot;: גם כאן חשוב לדעת שנגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(h'\\)</span> לא יכולה לקפוץ בקפיצה (משפטים 8.10–8.12), אף שנגזרת כן יכולה לא להיות רציפה באי-רציפות ממין שני.</li></ul></div></div>"}],"similar":"","mc":{"answer":"ד"}},"7":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>תהי <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> הסדרה שאיבריה הם: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0,1,0,2,0,3,0,4,\\dots\\)</span>.</span> אז א. <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> מתכנסת במובן הרחב. ב. <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\overline{\\lim}_{n\\to\\infty} a_n = \\sup\\{a_n \\mid n\\in\\mathbb N\\}\\)</span>.</span> ג. <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\underline{\\lim}_{n\\to\\infty} a_n = \\inf\\{a_n \\mid n\\in\\mathbb N\\}\\)</span>.</span> ד. כל מספר טבעי הוא גבול חלקי של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span>.</span> ה. כל הטענות הנ״ל אינן נכונות.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">הגבול התחתון של הסדרה הוא <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> וגם האינפימום (המינימום) של קבוצת איבריה הוא <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> ולכן הם שווים! לעומת זאת הסופרימום כלל אינו קיים כי האיברים לא חסומים מלעיל.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: הגבול התחתון של הסדרה הוא <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> וגם האינפימום (המינימום) של קבוצת איבריה הוא <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> ולכן הם שווים! לעומת זאת הסופרימום כלל אינו קיים כי האיברים לא חסומים מלעיל.</p>\n<p><strong>תמונה בראש</strong>: שימו לב להבדל הדק שבין תקרה לרצפה בסדרה הזו: כל מספר זוגי קופץ לגובה חדש <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(1, 2, 3, 4, \\dots\\)</span>),</span> אז אין שום תקרה קבועה מעל כל האיברים — הקבוצה לא חסומה מלמעלה ולכן אין לה סופרמום <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\sup\\)</span></span> לא קיים בקורס!). אבל מלמטה? כולם גדולים או שווים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> מופיע כל הזמן במקום האי־זוגי, אז גם הרצפה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\inf\\)</span>)</span> וגם היעד הנמוך ביותר <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\underline{\\lim}\\)</span>)</span> הם בדיוק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></p>\n<p><strong>עם מספרים</strong>: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_1=0, a_2=1, a_3=0, a_4=2, a_5=0, a_6=3,\\dots\\)</span>.</span> כל מספר חיובי <span class=\"math math-inline\" dir=\"ltr\">\\(k\\ge 1\\)</span> מופיע רק פעם אחת (במקום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2k\\)</span>)</span> ולכן אינו גבול חלקי! קבוצת האיברים היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{0, 1, 2, 3, \\dots\\}\\)</span>,</span> שהאינפימום שלה הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> ובדיוק כך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\underline{\\lim}_{n\\to\\infty} a_n = 0\\)</span>.</span></p>\n<p><strong>מושגים</strong>:</p>\n<ul><li><strong><span class=\"math math-inline\" dir=\"ltr\">\\(\\sup\\)</span> בקורס (משפט 3.6)</strong>: מוגדר <strong>רק</strong> עבור קבוצה לא ריקה שחסומה מלעיל. לקבוצה שאינה חסומה מלעיל אין <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sup\\)</span>!</span></li><li><strong><span class=\"math math-inline\" dir=\"ltr\">\\(\\inf\\)</span> (הגדרה 3.12)</strong>: לקבוצה לא ריקה שחסומה מלרע (כמו <span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,1,2,\\dots\\}\\)</span> החסומה מלרע <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>)</span></span> יש אינפימום יחיד; כשהמינימום קיים הוא שווה לאינפימום.</li><li><strong><span class=\"math math-inline\" dir=\"ltr\">\\(\\underline{\\lim}\\)</span> (גבול תחתון, הגדרה 3.42)</strong>: הגבול החלקי הקטן ביותר במובן הרחב.</li></ul></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;latex&quot;:&quot;y=0&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;latex&quot;:&quot;(1, 0)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;latex&quot;:&quot;(2, 1)&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;latex&quot;:&quot;(3, 0)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;latex&quot;:&quot;(4, 2)&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;latex&quot;:&quot;(5, 0)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;latex&quot;:&quot;(6, 3)&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;latex&quot;:&quot;(7, 0)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;latex&quot;:&quot;(8, 4)&quot;,&quot;color&quot;:&quot;#c74440&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: זכרו את ההבדל בין טענה ב לבין טענה ג!","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: זכרו את ההבדל בין טענה ב לבין טענה ג!</p><div class=\"callout-body\"><p>בסדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0,1,0,2,0,3,\\dots\\)</span>,</span> האם קבוצת האיברים חסומה מלעיל? ומה קורה מלרע — האם לקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,1,2,3,\\dots\\}\\)</span> קיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\inf\\)</span>?</span></p></div></div>"},{"title":"רמז 2: זהירות ממספר סופי של ביקורים עבור טענה ד!","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: זהירות ממספר סופי של ביקורים עבור טענה ד!</p><div class=\"callout-body\"><p>כמה פעמים מופיע המספר <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> בסדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0,1,0,2,0,3,0,4,\\dots\\)</span>?</span> לפי משפט 3.27, גבול חלקי סופי דורש <em>אינסוף</em> איברים בקרבתו!</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">תוכנית הפתרון</p><div class=\"callout-body\"><ol><li>נזהה במפורש את הנוסחה: <span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k-1}=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k}=k\\)</span>,</span></span> ואת קבוצת האיברים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,1,2,3,\\dots\\}\\)</span>.</span></li><li>נבדוק את <strong>א</strong>: תת-הסדרה האי-זוגית שואפת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> והזוגית <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span>,</span></span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> אינה מתכנסת במובן הרחב (א שגויה).</li><li>נבדוק את <strong>ב</strong>: הסדרה אינה חסומה מלעיל, ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\sup\\{a_n\\mid n\\in\\mathbb N\\}\\)</span> כלל אינו קיים (משפט 3.6), אף <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\overline{\\lim} a_n = \\infty\\)</span></span> במובן הרחב (ב שגויה).</li><li>נבדוק את <strong>ג</strong>: לקבוצת האיברים החיוביים-או-אפס יש מינימום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\inf\\{a_n\\}=0\\)</span>,</span> וגבולה התחתון הוא <span class=\"math math-inline\" dir=\"ltr\">\\(\\underline{\\lim} a_n = 0\\)</span> — לכן השוויון מתקיים! (ג נכונה.)</li><li>נבדוק את <strong>ד</strong>: כל טבעי <span class=\"math math-inline\" dir=\"ltr\">\\(k\\ge 1\\)</span> מופיע פעם אחת בלבד, ולכן לפי משפט 3.27 אינו גבול חלקי (ד שגויה).</li></ol></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון</p><div class=\"callout-body\"><p><strong>התשובה: ג.</strong></p>\n<p>נכתוב את הסדרה במפורש: לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\in\\mathbb N\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k-1}=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k}=k\\)</span>.</span></span> קבוצת ערכי הסדרה היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{a_n \\mid n\\in\\mathbb N\\} = \\{0, 1, 2, 3, \\dots\\}\\)</span>.</span></p>\n<p><strong>שלב 1: שלילת טענה א</strong> תת-הסדרה של המקומות האי-זוגיים היא הסדרה הקבועה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k-1}=0\\to 0\\)</span>,</span> ותת-הסדרה של המקומות הזוגיים היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k}=k\\to\\infty\\)</span>.</span> לפי משפט 3.25, שתי תתי-סדרות עם גבולות שונים במובן הרחב <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(0\\ne\\infty\\)</span>)</span> שוללות התכנסות של <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> גם במובן הרחב. טענה <strong>א</strong> שגויה.</p>\n<p><strong>שלב 2: שלילת טענה ב</strong> במובן הרחב (הגדרה 3.42), מאחר שתת-הסדרה הזוגית שואפת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\overline{\\lim}_{n\\to\\infty} a_n = \\infty\\)</span>.</span> אולם הקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(\\{a_n \\mid n\\in\\mathbb N\\} = \\{0,1,2,3,\\dots\\}\\)</span> אינה חסומה מלעיל (תכונת ארכימדס, משפט 1.60), ולכן לפי משפט 3.6 <strong>לא קיים</strong> לה סופרמום (איננו כותבים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sup = \\infty\\)</span>).</span> מכאן שטענה <strong>ב</strong> שגויה.</p>\n<p><strong>שלב 3: אימות טענה ג</strong></p>\n<ul><li>הקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(\\{a_n \\mid n\\in\\mathbb N\\} = \\{0,1,2,3,\\dots\\}\\)</span> לא ריקה, וחסומה מלרע על ידי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> עצמו שייך לקבוצה; לכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\inf\\{a_n \\mid n\\in\\mathbb N\\} = \\min\\{a_n \\mid n\\in\\mathbb N\\} = 0\\)</span> (הגדרה 3.12).</li><li>מצד שני, <span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k-1}=0\\to 0\\)</span> מראה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> הוא גבול חלקי של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span>,</span> ומכך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\ge 0\\)</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> כל גבול חלקי במובן הרחב מקיים <span class=\"math math-inline\" dir=\"ltr\">\\(L\\ge 0\\)</span> (משפט 2.31). לפיכך הגבול החלקי הקטן ביותר במובן הרחב הוא <span class=\"math math-inline\" dir=\"ltr\">\\(\\underline{\\lim}_{n\\to\\infty} a_n = 0\\)</span> (הגדרה 3.42).</li></ul>\n<p>מכאן שמתקיים השוויון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\underline{\\lim}_{n\\to\\infty} a_n = 0 = \\inf\\{a_n \\mid n\\in\\mathbb N\\}\\)</span>,</span> וטענה <strong>ג</strong> <strong>נכונה</strong>!</p>\n<p><strong>שלב 4: שלילת טענה ד (וה)</strong> לכל מספר טבעי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\ge 1\\)</span>,</span> אם <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ne 2k\\)</span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> שווה או <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> או למספר טבעי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(m\\ne k\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|a_n - k| \\ge 1\\)</span>.</span> כלומר בסביבה <span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-k| &lt; \\frac{1}{2}\\)</span> נמצא רק אינדקס אחד בלבד <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(n=2k\\)</span>),</span> ולכן לפי משפט 3.27 המספר <span class=\"math math-inline\" dir=\"ltr\">\\(k\\)</span> <strong>אינו</strong> גבול חלקי של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span>.</span> (למעשה קבוצת הגבולות החלקיים במובן הרחב היא <span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,\\infty\\}\\)</span> בלבד.) טענה <strong>ד</strong> שגויה, ומכיוון ש-<strong>ג</strong> נכונה גם <strong>ה</strong> שגויה. <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>התשובה: ג.</strong></p>\n<p>נכתוב את הסדרה במפורש: לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\in\\mathbb N\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k-1}=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k}=k\\)</span>.</span></span> קבוצת ערכי הסדרה היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{a_n \\mid n\\in\\mathbb N\\} = \\{0, 1, 2, 3, \\dots\\}\\)</span>.</span></p>\n<p><strong>שלב 1: שלילת טענה א</strong> תת-הסדרה של המקומות האי-זוגיים היא הסדרה הקבועה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k-1}=0\\to 0\\)</span>,</span> ותת-הסדרה של המקומות הזוגיים היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k}=k\\to\\infty\\)</span>.</span> לפי משפט 3.25, שתי תתי-סדרות עם גבולות שונים במובן הרחב <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(0\\ne\\infty\\)</span>)</span> שוללות התכנסות של <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> גם במובן הרחב. טענה <strong>א</strong> שגויה.</p>","<p><strong>שלב 2: שלילת טענה ב</strong> במובן הרחב (הגדרה 3.42), מאחר שתת-הסדרה הזוגית שואפת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\overline{\\lim}_{n\\to\\infty} a_n = \\infty\\)</span>.</span> אולם הקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(\\{a_n \\mid n\\in\\mathbb N\\} = \\{0,1,2,3,\\dots\\}\\)</span> אינה חסומה מלעיל (תכונת ארכימדס, משפט 1.60), ולכן לפי משפט 3.6 <strong>לא קיים</strong> לה סופרמום (איננו כותבים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sup = \\infty\\)</span>).</span> מכאן שטענה <strong>ב</strong> שגויה.</p>","<p><strong>שלב 3: אימות טענה ג</strong></p>\n<ul><li>הקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(\\{a_n \\mid n\\in\\mathbb N\\} = \\{0,1,2,3,\\dots\\}\\)</span> לא ריקה, וחסומה מלרע על ידי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> עצמו שייך לקבוצה; לכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\inf\\{a_n \\mid n\\in\\mathbb N\\} = \\min\\{a_n \\mid n\\in\\mathbb N\\} = 0\\)</span> (הגדרה 3.12).</li><li>מצד שני, <span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k-1}=0\\to 0\\)</span> מראה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> הוא גבול חלקי של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span>,</span> ומכך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\ge 0\\)</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> כל גבול חלקי במובן הרחב מקיים <span class=\"math math-inline\" dir=\"ltr\">\\(L\\ge 0\\)</span> (משפט 2.31). לפיכך הגבול החלקי הקטן ביותר במובן הרחב הוא <span class=\"math math-inline\" dir=\"ltr\">\\(\\underline{\\lim}_{n\\to\\infty} a_n = 0\\)</span> (הגדרה 3.42).</li></ul>\n<p>מכאן שמתקיים השוויון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\underline{\\lim}_{n\\to\\infty} a_n = 0 = \\inf\\{a_n \\mid n\\in\\mathbb N\\}\\)</span>,</span> וטענה <strong>ג</strong> <strong>נכונה</strong>!</p>","<p><strong>שלב 4: שלילת טענה ד (וה)</strong> לכל מספר טבעי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\ge 1\\)</span>,</span> אם <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ne 2k\\)</span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> שווה או <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> או למספר טבעי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(m\\ne k\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|a_n - k| \\ge 1\\)</span>.</span> כלומר בסביבה <span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-k| &lt; \\frac{1}{2}\\)</span> נמצא רק אינדקס אחד בלבד <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(n=2k\\)</span>),</span> ולכן לפי משפט 3.27 המספר <span class=\"math math-inline\" dir=\"ltr\">\\(k\\)</span> <strong>אינו</strong> גבול חלקי של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span>.</span> (למעשה קבוצת הגבולות החלקיים במובן הרחב היא <span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,\\infty\\}\\)</span> בלבד.) טענה <strong>ד</strong> שגויה, ומכיוון ש-<strong>ג</strong> נכונה גם <strong>ה</strong> שגויה. <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות שכדאי להימנע מהן</p><div class=\"callout-body\"><ul><li>לפסול אוטומטית את <strong>ג</strong> מתוך הרגל משאלות דומות שבהן ההשוואה הייתה עם <code dir=\"auto\">sup</code> או עם סדרה שאינה מתחילה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>!</span></span> כאן גם <code dir=\"auto\">inf</code> קיים וגם הגבול התחתון הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> כך ששניהם שווים.</li><li>לחשוב ש-&quot;<span class=\"math math-inline\" dir=\"ltr\">\\(\\sup\\{0,1,2,\\dots\\} = \\infty\\)</span>&quot; ולכן לבחור את ב — בקורס שלנו סופרמום קיים <strong>רק</strong> לקבוצה חסומה מלעיל (משפט 3.6).</li></ul></div></div>"}],"similar":"<p><strong>שאלות דומות</strong>: <a href=\"#/exams/29/q6\">2024א · מועד 81, שאלה 6</a>, <a href=\"#/exams/31/q6\">2024א · מועד 96, שאלה 6</a></p>","mc":{"answer":"ג"}},"8":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4x\\arctan 2x \\ge \\ln(1+4x^2)\\)</span>.</span> א. הטענה נכונה. ב. הטענה אינה נכונה.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כשמעבירים אגף וגוזרים, המנה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{8x}{1+4x^2}\\)</span> מצטמצמת לגמרי ונשארים עם הנגזרת הנקייה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4\\arctan 2x\\)</span>,</span> שמראה שהפרש האגפים עולה <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> לשני הצדדים!</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כשמעבירים אגף וגוזרים, המנה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{8x}{1+4x^2}\\)</span> מצטמצמת לגמרי ונשארים עם הנגזרת הנקייה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4\\arctan 2x\\)</span>,</span> שמראה שהפרש האגפים עולה <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> לשני הצדדים!</p>\n<p><strong>תמונה בראש</strong>: שתי הפונקציות סימטריות לחלוטין סביב ציר <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(y\\)</span></span> (זוגיות) ונפגשות בדיוק בגובה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> בראשית <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span>.</span> כשזזים ימינה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span></span> אגף שמאל מטפס תלול יותר מאגף ימין (כי ההפרש ביניהן בעל נגזרת חיובית <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4\\arctan 2x &gt; 0\\)</span>),</span> ובזכות הסימטריה הזוגית אותו יתרון נשמר אוטומטית גם לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>!</span></p>\n<p><strong>עם מספרים</strong>: <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>:</span></span> שני האגפים שווים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0.5\\)</span>:</span></span> אגף שמאל הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\arctan 1 = 2\\cdot\\frac{\\pi}{4} = \\frac{\\pi}{2}\\approx 1.571\\)</span>,</span> ואילו אגף ימין הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln(2)\\approx 0.693\\)</span>,</span> ובאמת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1.571 &gt; 0.693\\)</span>.</span></p>\n<p><strong>מושגים</strong>:</p>\n<ul><li><strong>פונקציה זוגית</strong>: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(-x)=h(x)\\)</span>,</span> שמאפשרת לבדוק אי־שוויון רק עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 0\\)</span> (או לבדוק מונוטוניות בכל צד לחוד).</li><li><strong>בדיקת אי־שוויון בעזרת נגזרת (משפט 8.18)</strong>: ההפרש שווה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> ואם נגזרתו חיובית <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span></span> הוא חיובי בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>.</span></li></ul></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;latex&quot;:&quot;f(x)=4x\\\\arctan(2x)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;latex&quot;:&quot;g(x)=\\\\ln(1+4x^2)&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;latex&quot;:&quot;(0, 0)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;h(0)=0&quot;},{&quot;latex&quot;:&quot;(0.5, 1.5708)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;π/2 ≈ 1.57&quot;},{&quot;latex&quot;:&quot;(0.5, 0.6931)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;ln 2 ≈ 0.69&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: הגדירו פונקציית הפרש וגזרו לפי כלל המכפלה והשרשרת","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: הגדירו פונקציית הפרש וגזרו לפי כלל המכפלה והשרשרת</p><div class=\"callout-body\"><p>סמנו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=4x\\arctan(2x)-\\ln(1+4x^2)\\)</span>.</span> שימו לב מה קורה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\((\\arctan 2x)' = \\frac{2}{1+4x^2}\\)</span></span> כשמכפילים אותו <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4x\\)</span>!</span></span></p></div></div>"},{"title":"רמז 2: אל תשכחו את ה-$x<0$!","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: אל תשכחו את <span class=\"nobr\">ה-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>!</span></span></p><div class=\"callout-body\"><p>אחרי שתוכיחו <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)\\ge 0\\)</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 0\\)</span> בעזרת משפט 8.18, נצלו את הזוגיות <span class=\"math math-inline\" dir=\"ltr\">\\(h(-x)=h(x)\\)</span> (כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((-x)\\arctan(-2x)=x\\arctan 2x\\)</span>),</span> או בדקו בנפרד <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h'(x)&lt;0\\)</span></span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((-\\infty,0)\\)</span>.</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">תוכנית הפתרון</p><div class=\"callout-body\"><ol><li>נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=4x\\arctan(2x)-\\ln(1+4x^2)\\)</span> בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> ונבדוק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(0)=0\\)</span>.</span></li><li>נגזור את <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> (משפטים 7.14, 7.21, 7.28, 7.29) ונקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'(x)=4\\arctan(2x)\\)</span>.</span></li><li><span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>,</span></span> נגזרתו חיובית <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span></span> ולכן ממשפט 8.18 מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)\\ge h(0)=0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 0\\)</span>.</span></li><li>מזוגיות הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h(-x)=h(x)\\)</span> (כי <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan\\)</span> אי-זוגית <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(4x^2\\)</span></span> זוגית) נובע <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)\\ge 0\\)</span> גם לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>.</span></li></ol></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון</p><div class=\"callout-body\"><p><strong>התשובה: א (הטענה נכונה).</strong></p>\n<p><strong>שלב 1: הגדרת פונקציית ההפרש וערך <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span></strong> נגדיר על כל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> את הפונקציה</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(x) = 4x\\arctan(2x) - \\ln(1+4x^2).\\]</div>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(1+4x^2 \\ge 1 &gt; 0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>,</span> הפונקציה מוגדרת, רציפה וגזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (משפטים 7.13, 7.14, 7.21, 7.28, 7.29). <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(0) = 4\\cdot 0\\cdot\\arctan 0 - \\ln 1 = 0.\\]</div>\n<p><strong>שלב 2: חישוב הנגזרת וסימנה בקרן החיובית</strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> נגזור לפי כלל המכפלה וכלל השרשרת:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h'(x) = 4\\arctan(2x) + 4x\\cdot\\frac{2}{1+(2x)^2} - \\frac{8x}{1+4x^2} = 4\\arctan(2x) + \\frac{8x}{1+4x^2} - \\frac{8x}{1+4x^2} = 4\\arctan(2x).\\]</div>\n<p>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2x&gt;0\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan(2x) &gt; \\arctan 0 = 0\\)</span> (כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan:\\mathbb R\\to(-\\frac{\\pi}{2},\\frac{\\pi}{2})\\)</span></span> עולה ממש, משפט 5.43 / טענה 5.44). מכאן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h'(x) &gt; 0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span>.</span> מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>,</span></span> לפי משפט 8.18 <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> עולה ממש <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>,</span></span> ולכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 0\\)</span> מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(x) \\ge h(0) = 0.\\]</div>\n<p><strong>שלב 3: הרחבה לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span> באמצעות זוגיות</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan\\)</span> היא אי-זוגית <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan(-t)=-\\arctan t\\)</span>),</span> ולכן לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(-x) = 4(-x)\\arctan(-2x) - \\ln(1+4(-x)^2) = 4x\\arctan(2x) - \\ln(1+4x^2) = h(x).\\]</div>\n<p>לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-x &gt; 0\\)</span>,</span> ומאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span></span> אינה שלילית על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>,</span> מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(x) = h(-x) &gt; 0.\\]</div>\n<p>בסיכום, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(x)\\ge 0\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4x\\arctan 2x \\ge \\ln(1+4x^2)\\)</span>,</span> וטענה <strong>א</strong> נכונה. <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>התשובה: א (הטענה נכונה).</strong></p>\n<p><strong>שלב 1: הגדרת פונקציית ההפרש וערך <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span></strong> נגדיר על כל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> את הפונקציה</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(x) = 4x\\arctan(2x) - \\ln(1+4x^2).\\]</div>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(1+4x^2 \\ge 1 &gt; 0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>,</span> הפונקציה מוגדרת, רציפה וגזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (משפטים 7.13, 7.14, 7.21, 7.28, 7.29). <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(0) = 4\\cdot 0\\cdot\\arctan 0 - \\ln 1 = 0.\\]</div>","<p><strong>שלב 2: חישוב הנגזרת וסימנה בקרן החיובית</strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> נגזור לפי כלל המכפלה וכלל השרשרת:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h'(x) = 4\\arctan(2x) + 4x\\cdot\\frac{2}{1+(2x)^2} - \\frac{8x}{1+4x^2} = 4\\arctan(2x) + \\frac{8x}{1+4x^2} - \\frac{8x}{1+4x^2} = 4\\arctan(2x).\\]</div>\n<p>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2x&gt;0\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan(2x) &gt; \\arctan 0 = 0\\)</span> (כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan:\\mathbb R\\to(-\\frac{\\pi}{2},\\frac{\\pi}{2})\\)</span></span> עולה ממש, משפט 5.43 / טענה 5.44). מכאן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h'(x) &gt; 0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span>.</span> מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>,</span></span> לפי משפט 8.18 <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> עולה ממש <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>,</span></span> ולכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 0\\)</span> מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(x) \\ge h(0) = 0.\\]</div>","<p><strong>שלב 3: הרחבה לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span> באמצעות זוגיות</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan\\)</span> היא אי-זוגית <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan(-t)=-\\arctan t\\)</span>),</span> ולכן לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(-x) = 4(-x)\\arctan(-2x) - \\ln(1+4(-x)^2) = 4x\\arctan(2x) - \\ln(1+4x^2) = h(x).\\]</div>\n<p>לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-x &gt; 0\\)</span>,</span> ומאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span></span> אינה שלילית על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>,</span> מתקיים</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(x) = h(-x) &gt; 0.\\]</div>\n<p>בסיכום, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(x)\\ge 0\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4x\\arctan 2x \\ge \\ln(1+4x^2)\\)</span>,</span> וטענה <strong>א</strong> נכונה. <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות שכדאי להימנע מהן</p><div class=\"callout-body\"><ul><li>לשכוח את הנגזרת הפנימית של <span class=\"math math-inline\" dir=\"ltr\">\\(2x\\)</span> בתוך <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan(2x)\\)</span> או בתוך <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln(1+4x^2)\\)</span> — אם שוכחים אותה באחד מהם, השברים <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{8x}{1+4x^2}\\)</span> אינם מתקזזים!</li><li>להוכיח רק עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> ולשכוח להשלים את ההוכחה עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span></li></ul></div></div>"}],"similar":"<p><strong>שאלות דומות</strong>: <a href=\"#/exams/30/q8\">2024א · מועד 88, שאלה 8</a></p>","mc":{"answer":"א"}},"9":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>תהיינה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n), (b_n)\\)</span> שתי סדרות שכל איבריהן שונים <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p>\n<ol><li>אם <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> אפסה <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span></span> מתבדרת אז <span class=\"math math-inline\" dir=\"ltr\">\\((a_n b_n)\\)</span> חסומה.</li><li>אם <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> אינה חסומה <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span></span> מתבדרת אז <span class=\"math math-inline\" dir=\"ltr\">\\((a_n b_n)\\)</span> אינה חסומה.</li></ol>\n<p>הטענות הנכונות הן: א. 1 ב. 2 ג. 1, 2 ד. אף טענה אינה נכונה</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">שתי הטענות שגויות — אם <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> מתבדרת לאינסוף מהר יותר ממה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span></span> מתאפסת אז המכפלה בורחת, ואם <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> גדולה רק באינדקסים מסוימים בזמן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span></span> מקזזת אותה שם ומתפרעת במקום אחר, המכפלה יכולה להיות קבועה ממש!</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: שתי הטענות שגויות — אם <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> מתבדרת לאינסוף מהר יותר ממה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span></span> מתאפסת אז המכפלה בורחת, ואם <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> גדולה רק באינדקסים מסוימים בזמן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span></span> מקזזת אותה שם ומתפרעת במקום אחר, המכפלה יכולה להיות קבועה ממש!</p>\n<p><strong>תמונה בראש</strong>: בטענה 1, <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> היא אפסה, לא &quot;קטנה מספיק&quot;: משפט &quot;אפסה כפול <em>חסומה</em>&quot; דורש <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\)</span></span> תהיה חסומה, ואם <span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\)</span> רצה לאינסוף מהר מדי (כמו <span class=\"math math-inline\" dir=\"ltr\">\\(n^2\\)</span> מול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n}\\)</span>),</span> היא גוררת את המכפלה לאינסוף. בטענה 2, סדרה לא חסומה אינה חייבת להיות ענקית בכל אינדקס: מותר לה להיות ענקית במקומות האי־זוגיים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>)</span> וסתם <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> בזוגיים, בזמן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\)</span></span> לוקחת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n}\\)</span> באי־זוגיים <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> בזוגיים (ולכן מתבדרת כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\ne 1\\)</span>!),</span> והמכפלה בכל מקום שווה בדיוק <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></p>\n<p><strong>עם מספרים</strong>: לטענה 1 קחו <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=\\frac{1}{n}\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_n=n^2\\)</span>:</span></span> המכפלה היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>,</span> לא חסומה. לטענה 2 קחו <span class=\"math math-inline\" dir=\"ltr\">\\(a_n = 1, 1, 3, 1, 5, 1, \\dots\\)</span> (אי־זוגיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>,</span> זוגיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(b_n = 1, 1, \\frac{1}{3}, 1, \\frac{1}{5}, 1, \\dots\\)</span></span> (אי־זוגיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n}\\)</span>,</span> זוגיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>):</span> שתיהן שונות מאפס, <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> לא חסומה, <span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\)</span> מתבדרת (תת־סדרה אחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> ואחת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>),</span></span> והמכפלה <span class=\"math math-inline\" dir=\"ltr\">\\(a_n b_n = 1,1,1,1,\\dots\\)</span> חסומה בהחלט!</p>\n<p><strong>מושגים</strong>:</p>\n<ul><li><strong>סדרה אפסה (הגדרה 2.21)</strong>: סדרה שגבולה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></li><li><strong>הפרכה באמצעות דוגמה נגדית</strong>: יש לוודא שכל התנאים מתקיימים! כאן חשוב במיוחד לבדוק שאף איבר אינו <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">וש-<span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span></span> <em>באמת</em> מתבדרת (לא שואפת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>!).</span></span></li></ul></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;latex&quot;:&quot;(1, 1)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;latex&quot;:&quot;(2, 1)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;latex&quot;:&quot;(3, 3)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;a_n עולה באי-זוגיים&quot;},{&quot;latex&quot;:&quot;(4, 1)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;latex&quot;:&quot;(5, 5)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;latex&quot;:&quot;(3, 0.3333)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;b_n=1/n באי-זוגיים&quot;},{&quot;latex&quot;:&quot;(5, 0.2)&quot;,&quot;color&quot;:&quot;#c74440&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: בטענה 1, נסו להכריע את המכפלה בעזרת $b_n$ ששואפת לאינסוף מהר יותר מ-$\\frac{1}{a_n}$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: בטענה 1, נסו להכריע את המכפלה בעזרת <span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\)</span> ששואפת לאינסוף מהר יותר <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{a_n}\\)</span></span></p><div class=\"callout-body\"><p>למשל <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=\\frac{1}{n}\\)</span> (אפסה, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\ne 0\\)</span>)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(b_n=n^2\\)</span></span> (מתבדרת, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\ne 0\\)</span>).</span> מהו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n b_n\\)</span>?</span></p></div></div>"},{"title":"רמז 2: בטענה 2, זהירות! אסור לקחת $b_n=\\frac{1}{n}$ כי אז $b_n$ מתכנסת!","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: בטענה 2, זהירות! אסור לקחת <span class=\"math math-inline\" dir=\"ltr\">\\(b_n=\\frac{1}{n}\\)</span> כי אז <span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\)</span> מתכנסת!</p><div class=\"callout-body\"><p>איך פותרים את זה כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span></span> תהיה <em>מתבדרת</em> ובכל זאת תקזז את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span>?</span> מגדירים התנהגות מפוצלת בין זוגיים לאי-זוגיים: במקומות האי-זוגיים <span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k-1}=2k-1\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_{2k-1}=\\frac{1}{2k-1}\\)</span>,</span></span> ובמקומות הזוגיים <span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k}=1\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_{2k}=1\\)</span>!</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">תוכנית הפתרון</p><div class=\"callout-body\"><ol><li>לטענה 1 נבנה <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=\\frac{1}{n}\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_n=n^2\\)</span>,</span></span> נוודא שכל התנאים מתקיימים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a_n,b_n\\ne 0\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> אפסה, <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> מתבדרת) ונראה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n b_n = n\\)</span></span> אינה חסומה.</li><li>לטענה 2 נבנה <span class=\"math math-inline\" dir=\"ltr\">\\(a_n = n\\)</span> (לאי-זוגי) <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> (לזוגי), <span class=\"math math-inline\" dir=\"ltr\">\\(b_n = \\frac{1}{n}\\)</span> (לאי-זוגי) <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> (לזוגי), נוודא <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n,b_n\\ne 0\\)</span>,</span></span> <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> אינה חסומה, <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> מתבדרת כי תת-סדרותיה שואפות <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> ואילו <span class=\"math math-inline\" dir=\"ltr\">\\(a_n b_n = 1\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> ולכן חסומה.</li><li>נסכם שאף טענה אינה נכונה (תשובה ד).</li></ol></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון</p><div class=\"callout-body\"><p><strong>התשובה: ד (אף טענה אינה נכונה).</strong></p>\n<p><strong>שלב 1: הפרכת טענה 1</strong> נבחר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[a_n = \\frac{1}{n}, \\qquad b_n = n^2.\\]</div>\n<p>נבדוק את כל תנאי הטענה:</p>\n<ul><li>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\ne 0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\ne 0\\)</span>.</span></span></li><li><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} a_n = \\lim_{n\\to\\infty}\\frac{1}{n} = 0\\)</span> (טענה 2.10), ולכן <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> אפסה (הגדרה 2.21).</li><li><span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_n = n^2 \\ge n \\to \\infty\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> מתבדרת (אינה מתכנסת לגבול סופי, משפט 2.16).</li></ul>\n<p>עם זאת, המכפלה היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n b_n = \\frac{1}{n}\\cdot n^2 = n\\)</span>,</span> שאינה חסומה מלעיל (משפט 1.60), ולכן אינה חסומה. מכאן שטענה 1 <strong>אינה נכונה</strong>.</p>\n<p><strong>שלב 2: הפרכת טענה 2</strong> נגדיר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[a_n = \\begin{cases} n &amp; n \\text{ אי-זוגי} \\\\ 1 &amp; n \\text{ זוגי} \\end{cases}, \\qquad b_n = \\begin{cases} \\frac{1}{n} &amp; n \\text{ אי-זוגי} \\\\ 1 &amp; n \\text{ זוגי} \\end{cases}.\\]</div>\n<p>נבדוק את כל תנאי הטענה:</p>\n<ul><li>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(a_n &gt; 0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_n &gt; 0\\)</span>,</span></span> ובפרט כל האיברים שונים <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></li><li>הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> אינה חסומה, כי תת-הסדרה האי-זוגית מקיימת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k-1}=2k-1\\to\\infty\\)</span>.</span></li><li>הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> מתבדרת (אין לה גבול סופי), משום שתת-הסדרה הזוגית שואפת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(b_{2k}=1\\to 1\\)</span>)</span> ואילו תת-הסדרה האי-זוגית שואפת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(b_{2k-1}=\\frac{1}{2k-1}\\to 0\\)</span>),</span> בסתירה לירושת הגבול (משפט 3.25) וליחידות הגבול (משפט 2.12).</li></ul>\n<p>עם זאת, לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>:</span></p>\n<ul><li>אם <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> אי-זוגי: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n b_n = n \\cdot \\frac{1}{n} = 1\\)</span>.</span></li><li>אם <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> זוגי: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n b_n = 1 \\cdot 1 = 1\\)</span>.</span></li></ul>\n<p>לכן סדרת המכפלה היא הסדרה הקבועה <span class=\"math math-inline\" dir=\"ltr\">\\(a_n b_n = 1\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>,</span> והיא כמובן חסומה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(|a_n b_n|\\le 1\\)</span>).</span> מכאן שטענה 2 <strong>אינה נכונה</strong>.</p>\n<p>מאחר ששתי הטענות שגויות, התשובה היא <strong>ד</strong>. <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>התשובה: ד (אף טענה אינה נכונה).</strong></p>\n<p><strong>שלב 1: הפרכת טענה 1</strong> נבחר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[a_n = \\frac{1}{n}, \\qquad b_n = n^2.\\]</div>\n<p>נבדוק את כל תנאי הטענה:</p>\n<ul><li>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\ne 0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\ne 0\\)</span>.</span></span></li><li><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} a_n = \\lim_{n\\to\\infty}\\frac{1}{n} = 0\\)</span> (טענה 2.10), ולכן <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> אפסה (הגדרה 2.21).</li><li><span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_n = n^2 \\ge n \\to \\infty\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> מתבדרת (אינה מתכנסת לגבול סופי, משפט 2.16).</li></ul>\n<p>עם זאת, המכפלה היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n b_n = \\frac{1}{n}\\cdot n^2 = n\\)</span>,</span> שאינה חסומה מלעיל (משפט 1.60), ולכן אינה חסומה. מכאן שטענה 1 <strong>אינה נכונה</strong>.</p>","<p><strong>שלב 2: הפרכת טענה 2</strong> נגדיר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[a_n = \\begin{cases} n &amp; n \\text{ אי-זוגי} \\\\ 1 &amp; n \\text{ זוגי} \\end{cases}, \\qquad b_n = \\begin{cases} \\frac{1}{n} &amp; n \\text{ אי-זוגי} \\\\ 1 &amp; n \\text{ זוגי} \\end{cases}.\\]</div>\n<p>נבדוק את כל תנאי הטענה:</p>\n<ul><li>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(a_n &gt; 0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_n &gt; 0\\)</span>,</span></span> ובפרט כל האיברים שונים <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></li><li>הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> אינה חסומה, כי תת-הסדרה האי-זוגית מקיימת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k-1}=2k-1\\to\\infty\\)</span>.</span></li><li>הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> מתבדרת (אין לה גבול סופי), משום שתת-הסדרה הזוגית שואפת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(b_{2k}=1\\to 1\\)</span>)</span> ואילו תת-הסדרה האי-זוגית שואפת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(b_{2k-1}=\\frac{1}{2k-1}\\to 0\\)</span>),</span> בסתירה לירושת הגבול (משפט 3.25) וליחידות הגבול (משפט 2.12).</li></ul>\n<p>עם זאת, לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>:</span></p>\n<ul><li>אם <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> אי-זוגי: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n b_n = n \\cdot \\frac{1}{n} = 1\\)</span>.</span></li><li>אם <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> זוגי: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n b_n = 1 \\cdot 1 = 1\\)</span>.</span></li></ul>\n<p>לכן סדרת המכפלה היא הסדרה הקבועה <span class=\"math math-inline\" dir=\"ltr\">\\(a_n b_n = 1\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>,</span> והיא כמובן חסומה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(|a_n b_n|\\le 1\\)</span>).</span> מכאן שטענה 2 <strong>אינה נכונה</strong>.</p>\n<p>מאחר ששתי הטענות שגויות, התשובה היא <strong>ד</strong>. <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות שכדאי להימנע מהן</p><div class=\"callout-body\"><ul><li>בטענה 2, להציע בתור דוגמה נגדית <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=n\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(b_n=\\frac{1}{n}\\)</span></span> — הדוגמה הזו שגויה כי <span class=\"math math-inline\" dir=\"ltr\">\\(b_n=\\frac{1}{n}\\)</span> <strong>מתכנסת</strong> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> ולא מתבדרת כנדרש בשאלה! הפיצול לזוגיים ואי-זוגיים גורם <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span></span> להתבדר ועדיין מאפשר <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n b_n\\)</span></span> להישאר חסומה.</li><li>להתבלבל בטענה 1 עם משפט 2.22 (&quot;אפסה כפול חסומה = אפסה&quot;): בלי חסימות של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span>,</span> המכפלה עלולה אפילו לברוח לאינסוף.</li></ul></div></div>"}],"similar":"","mc":{"1":false,"2":false}}};
